Object.assign(window.MLSysGuidedLessons, {"vol3:fig-vol3-access-prefilter":{"key":"vol3:fig-vol3-access-prefilter","figure_id":"fig-vol3-access-prefilter","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"Filtering Inside a Graph Walk","status":"ready","treatment":"annotated","question":"Why can an access mask make an eligible neighbor unreachable?","scope":"Authorization must hold during retrieval; these alternatives do not grant access to masked nodes.","regions":{"stall":{"x":0.03,"y":0.06,"w":0.44,"h":0.87,"label":"Masked traversal stalls"},"partition":{"x":0.55,"y":0.14,"w":0.4,"h":0.27,"label":"Partition by scope"},"entry":{"x":0.55,"y":0.44,"w":0.4,"h":0.24,"label":"Additional eligible entry"},"scan":{"x":0.55,"y":0.73,"w":0.41,"h":0.18,"label":"Exact scan of eligible set"}},"steps":[{"title":"Observe the broken route","description":"The walk reaches the circled node and stalls when intermediate nodes are masked. Eligible green nodes near q may exist without an admissible route to them.","focus":["stall"]},{"title":"Change the searchable topology","description":"Partitioning by scope builds traversal within the authorized subset. It changes the index organization rather than bypassing the scope mask.","focus":["partition"]},{"title":"Provide an eligible entry","description":"An extra entry point can reach a surviving connected component. It addresses routing coverage without making excluded nodes retrievable.","focus":["entry"]},{"title":"Scan when the subset is small","description":"For a selective eligible set, exact scoring can avoid graph reachability altogether. The cost depends on how many eligible vectors remain.","focus":["scan"]}],"artwork_reviewed":true,"art_sha1":"9f5b5828c8f7bbadddcadcdf11d768ebd5b368a7","art_kind":"svg","art_width":1200,"art_height":667,"art_structural_sha1":"c0597b5c1ec8995bc8cb8da95fe2740ae29dfebc"},"vol3:fig-vol3-allocation-axes":{"key":"vol3:fig-vol3-allocation-axes","figure_id":"fig-vol3-allocation-axes","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Three compute allocation topologies","status":"ready","treatment":"annotated","question":"How do depth, breadth, and feedback impose different dependencies on test-time work?","scope":"The panels show structure only; arrow length and illustrative path counts do not encode measured latency, cost, or correctness.","regions":{"depth":{"x":0.025,"y":0.06,"w":0.285,"h":0.89,"label":"Depth chain"},"breadth":{"x":0.365,"y":0.06,"w":0.285,"h":0.89,"label":"Sampled paths and selector"},"feedback":{"x":0.705,"y":0.06,"w":0.285,"h":0.89,"label":"Observation-conditioned revision"},"check":{"x":0.8,"y":0.32,"w":0.15,"h":0.36,"label":"Sandboxed check and observation"}},"steps":[{"title":"Depth extends one candidate","description":"Each reasoning segment depends on the preceding segment. Extra work lengthens a single candidate path before it reaches the output.","focus":["depth"]},{"title":"Breadth creates a selection problem","description":"Separate sampled paths start from the same input and converge on a selector. Generating more candidates does not itself decide which one to return.","focus":["breadth"]},{"title":"Feedback introduces new evidence","description":"The check produces an observation inside the sandbox. The revised candidate depends on both that observation and the original candidate, rather than on extra generation alone.","focus":["check","feedback"]}],"artwork_reviewed":true,"art_sha1":"4d7b0ebfa5c6ee94ad31ea3516eac9ec113f31fb","art_kind":"svg","art_width":1200,"art_height":506,"art_structural_sha1":"b768d206f7fb318bbddfa4ad192a57fc12e43304"},"vol3:fig-vol3-asynchronous-freshness-pipeline":{"key":"vol3:fig-vol3-asynchronous-freshness-pipeline","figure_id":"fig-vol3-asynchronous-freshness-pipeline","source":"books/vol3/17_rlvr/17_rlvr.qmd","title":"Group Barriers and Version-Checked Admission","status":"ready","treatment":"annotated","question":"What is exchanged for higher utilization when rollout slots release asynchronously?","scope":"The durations and version bound are illustrative. Version lag bounds do not bound parameter drift or replace objective-specific cohort requirements.","regions":{"barrier":{"x":0.02,"y":0.02,"w":0.96,"h":0.29,"label":"Synchronous barrier and idle slots"},"versions":{"x":0.02,"y":0.36,"w":0.96,"h":0.3,"label":"Asynchronous rollouts and version lags"},"verify":{"x":0.02,"y":0.775,"w":0.555,"h":0.095,"label":"Rollout verification and group buffer"},"admit":{"x":0.47,"y":0.74,"w":0.51,"h":0.23,"label":"Version admission and recorded exclusion"}},"steps":[{"title":"Reserved capacity waits at a barrier","description":"The short synchronous rollouts finish early but keep slots reserved until the longest member completes. Hatched regions show idle reserved time.","focus":["barrier"]},{"title":"Early release creates version lag","description":"Asynchronous collection releases slots while the trainer advances versions. A and B remain within the pictured lag bound; C crosses four version boundaries and is excluded.","focus":["versions"]},{"title":"Verification and grouping still matter","description":"A rollout receives pass, fail, or unavailable status before waiting in a bounded group buffer. Slot release does not resolve an unavailable verdict or complete a required cohort.","focus":["verify"]},{"title":"Admit with an explicit freshness check","description":"The trainer receives a record only through the version-lag decision. Exclusion records reason and cost; a bounded lag still permits distribution drift after large updates.","focus":["admit"]}],"artwork_reviewed":true,"art_sha1":"80d65de1af078ee163878c127e21337e626a46ab","art_kind":"svg","art_width":1200,"art_height":1024,"art_structural_sha1":"58d29f7603cbff971e7034f315297939700a6b28"},"vol3:fig-vol3-block-diagonal-mask":{"key":"vol3:fig-vol3-block-diagonal-mask","figure_id":"fig-vol3-block-diagonal-mask","source":"books/vol3/16_fine_tuning/16_fine_tuning.qmd","title":"Block-Diagonal Attention for Packed Examples","status":"ready","treatment":"annotated","question":"Why is a causal mask insufficient for independent packed examples?","scope":"The grids teach attention isolation; skipping masked kernel work is a separate implementation property.","regions":{"ordinary":{"x":0.03,"y":0.05,"w":0.44,"h":0.72,"label":"Ordinary causal mask"},"leak":{"x":0.16,"y":0.59,"w":0.19,"h":0.2,"label":"Cross-example score leak"},"blocked":{"x":0.65,"y":0.59,"w":0.19,"h":0.2,"label":"Excluded cross-example block"},"triangles":{"x":0.65,"y":0.26,"w":0.31,"h":0.53,"label":"Independent causal blocks"},"offsets":{"x":0.57,"y":0.81,"w":0.4,"h":0.07,"label":"Boundary offsets"},"legend":{"x":0.16,"y":0.9,"w":0.8,"h":0.06,"label":"Score and negative infinity legend"}},"steps":[{"title":"Find the packed example boundary","description":"Both eight-position grids place example one before example two. The ordinary causal rule lets every second-example query score earlier first-example keys.","focus":["ordinary"]},{"title":"Inspect the unintended context","description":"The red lower-left rectangle is the leak: example two can read context it will not have when served independently.","focus":["leak"]},{"title":"Mask across example identity","description":"The block-diagonal version assigns that cross-example rectangle negative infinity before softmax. Boundary offsets define which keys belong to the query’s example.","focus":["blocked","offsets"]},{"title":"Preserve each example’s causal history","description":"The two blue causal triangles remain valid inside their own blocks. Correct masking establishes isolation, not a guaranteed throughput improvement.","focus":["triangles","legend"]}],"artwork_reviewed":true,"art_sha1":"e8f1f577dddd40c693b2a169511821cec3ea98b5","art_kind":"svg","art_width":1200,"art_height":659,"art_structural_sha1":"e8f1f577dddd40c693b2a169511821cec3ea98b5"},"vol3:fig-vol3-canary-deployment-pipeline":{"key":"vol3:fig-vol3-canary-deployment-pipeline","figure_id":"fig-vol3-canary-deployment-pipeline","source":"books/vol3/14_agent_operations/14_agent_operations.qmd","title":"Staged Release and Its Hold Path","status":"ready","treatment":"annotated","question":"What changes when a release stage fails?","scope":"Each stage has its own evidence criterion; the diagram does not claim that a small canary makes exposed tasks safe.","regions":{"offline":{"x":0.02,"y":0.04,"w":0.22,"h":0.52,"label":"Offline paired comparison"},"shadow":{"x":0.27,"y":0.04,"w":0.22,"h":0.52,"label":"Shadow copies and drift"},"canary":{"x":0.52,"y":0.04,"w":0.22,"h":0.52,"label":"Bounded live canary"},"release":{"x":0.77,"y":0.04,"w":0.22,"h":0.52,"label":"Scoped release gate"},"stop":{"x":0.03,"y":0.8,"w":0.46,"h":0.14,"label":"Stop new admission"},"outstanding":{"x":0.51,"y":0.8,"w":0.47,"h":0.14,"label":"Retain outstanding ownership"}},"steps":[{"title":"Start with offline evidence","description":"Offline trials assign no live task to the candidate. Their paired acceptance interval must meet the declared margin before advancing.","focus":["offline"]},{"title":"Distinguish copies from live work","description":"Shadow execution uses authorized copies, not ownership of the live task. Tool-call drift is a different criterion from the offline acceptance interval.","focus":["shadow"]},{"title":"Monitor a bounded live share","description":"The canary receives the indicated live share rho, with a sequential monitor and hard tripwires. A wider release requires every declared gate criterion.","focus":["canary","release"]},{"title":"Hold admission without undoing effects","description":"An unmet criterion, problematic drift, or alarm stops new candidate admission. Outstanding work keeps its operation identities and owners and is settled by recovery, not rollback.","focus":["stop","outstanding"]}],"artwork_reviewed":true,"art_sha1":"9119f5c4dcbdbedf3699bbcc2fab28ee9d7303b1","art_kind":"svg","art_width":1200,"art_height":664,"art_structural_sha1":"8e8e7d2a3f2d97fb1cf4daae7eee66fdc3b7478c"},"vol3:fig-vol3-capability-attenuation":{"key":"vol3:fig-vol3-capability-attenuation","figure_id":"fig-vol3-capability-attenuation","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"Attenuation and What It Leaves Behind","status":"ready","treatment":"annotated","question":"What does attenuating one capability change about existing authority?","scope":"Derivation narrows a grant; it does not revoke the parent. Caveat verification must check every restriction.","regions":{"parent":{"x":0.03,"y":0.06,"w":0.94,"h":0.18,"label":"Parent edit grant"},"children":{"x":0.03,"y":0.24,"w":0.94,"h":0.25,"label":"Rejected and valid derived grants"},"chain":{"x":0.04,"y":0.58,"w":0.49,"h":0.36,"label":"Appended caveat chain"},"verify":{"x":0.56,"y":0.57,"w":0.4,"h":0.37,"label":"Verifier and chained authenticator"}},"steps":[{"title":"Start from the parent grant","description":"The edit grant allows read and write on the shown repository prefix until its expiry. This parent remains usable after deriving a child.","focus":["parent"]},{"title":"Reject broader authority","description":"The test child attempts execute rights absent from the parent and is rejected. The scan child narrows rights, object scope, and expiry and remains valid.","focus":["children"]},{"title":"Bind each added caveat","description":"The holder appends caveats to the chained authenticator. The verifier recomputes from its key and checks every caveat; possession does not allow deleting an earlier restriction.","focus":["chain","verify"]}],"artwork_reviewed":true,"art_sha1":"c5924093b0ba47272284e92fa4183a0aa1a9d8d2","art_kind":"svg","art_width":1200,"art_height":892,"art_structural_sha1":"abecaef497a97188188ec11925c4e3d129bf7601"},"vol3:fig-vol3-ch01-execution-lifecycle":{"key":"vol3:fig-vol3-ch01-execution-lifecycle","figure_id":"fig-vol3-ch01-execution-lifecycle","source":"books/vol3/01_introduction/01_introduction.qmd","title":"The Six-Phase Turn Lifecycle","status":"ready","treatment":"annotated","question":"Where can an agent turn wait, execute, or terminate?","scope":"This lifecycle is a control-flow map, not a claim that every proposal is authorized or every timeout proves failure.","regions":{"assembly":{"x":0.02,"y":0.06,"w":0.65,"h":0.2,"label":"Context and model invocation"},"grant":{"x":0.72,"y":0.06,"w":0.27,"h":0.2,"label":"Validate and authorize"},"wait":{"x":0.18,"y":0.28,"w":0.55,"h":0.15,"label":"Wait and rejected branches"},"tool":{"x":0.72,"y":0.49,"w":0.27,"h":0.21,"label":"Tool execution"},"assess":{"x":0.02,"y":0.49,"w":0.65,"h":0.21,"label":"Observation and assessment"},"exits":{"x":0.02,"y":0.76,"w":0.53,"h":0.2,"label":"Acceptance and nonacceptance"}},"steps":[{"title":"Assemble before calling","description":"The runtime assembles context and invokes the model. The resulting proposal proceeds to validation, rather than directly to tool execution.","focus":["assembly","grant"]},{"title":"Authorization controls execution","description":"Only the authorized path enters tool execution. Approval can pause in Wait; rejection follows the no-execution branch.","focus":["grant","wait","tool"]},{"title":"Evidence drives assessment","description":"Tool outcomes feed observation and evidence, then contract assessment. A timeout may leave the outcome unknown, so it is not automatically success or failure.","focus":["tool","assess"]},{"title":"Acceptance is an explicit exit","description":"Evidence meeting the contract permits acceptance. Otherwise the runtime may continue another turn, wait, or stop without acceptance.","focus":["assess","exits"]}],"artwork_reviewed":true,"art_sha1":"29b5013fd639d2d1d5cda469c6fc52221f279619","art_kind":"svg","art_width":1200,"art_height":628,"art_structural_sha1":"a9023068039f3ea4bda31d4ac36b1320291b6a0a"},"vol3:fig-vol3-chapter-dependencies":{"key":"vol3:fig-vol3-chapter-dependencies","figure_id":"fig-vol3-chapter-dependencies","source":"books/vol3/frontmatter/about.qmd","title":"Chapter Dependency Map","status":"ready","treatment":"annotated","question":"Which chapters support the core course, and where does the optional post-training branch rejoin it?","scope":"Arrows express recorded pedagogical dependencies, not runtime execution or every possible course order.","regions":{"foundation":{"x":0.15,"y":0.025,"w":0.81,"h":0.21,"label":"Introduction and model foundations"},"state":{"x":0.15,"y":0.26,"w":0.6,"h":0.08,"label":"Agent memory"},"authority":{"x":0.36,"y":0.38,"w":0.59,"h":0.08,"label":"Tool use"},"runtime":{"x":0.15,"y":0.49,"w":0.79,"h":0.08,"label":"Agent runtime and evaluation"},"optional":{"x":0.36,"y":0.62,"w":0.59,"h":0.08,"label":"Optional learning branch"},"scale":{"x":0.15,"y":0.73,"w":0.4,"h":0.2,"label":"Scale and synthesis"}},"steps":[{"title":"Begin with the foundation","description":"The solid path starts with the introduction and foundation model. The dashed Test-Time Compute chapter branches from the model chapter.","focus":["foundation"]},{"title":"Establish state and authority boundaries","description":"The memory band develops context, cache, and persistent memory. Tool use then establishes tool calling, sandbox, and security boundaries.","focus":["state","authority"]},{"title":"Measure the running system before learning","description":"The runtime band reaches evaluation and operation before the optional learning branch. Curation therefore starts from evidence collected by a running agent system.","focus":["runtime","optional"]},{"title":"Rejoin the core synthesis","description":"Multi-agent coordination and economics belong to the solid core. The conclusion builds on that core even when a course omits the dashed learning branch.","focus":["scale","optional"]}],"artwork_reviewed":true,"art_sha1":"a39f549d1bf467429419162b4695cd76e6290f17","art_kind":"svg","art_width":1200,"art_height":1408,"art_structural_sha1":"6178d170cc24ff43c6c58455bca673c0516408b5"},"vol3:fig-vol3-chunked-timeline":{"key":"vol3:fig-vol3-chunked-timeline","figure_id":"fig-vol3-chunked-timeline","source":"books/vol3/05_kv_cache/05_kv_cache.qmd","title":"Monolithic vs. Chunked Prefill","status":"ready","treatment":"annotated","question":"How can prefill scheduling change the gap between decode tokens?","scope":"The two timelines illustrate the shown fixed workload; chunking is not a universal throughput or latency guarantee.","regions":{"mono":{"x":0.03,"y":0.02,"w":0.95,"h":0.43,"label":"Monolithic prefill"},"chunks":{"x":0.03,"y":0.52,"w":0.95,"h":0.31,"label":"Eight prefill chunks"},"ticks":{"x":0.03,"y":0.8,"w":0.95,"h":0.16,"label":"Decode-token markers and time axis"}},"steps":[{"title":"One long admission","description":"The top panel admits the full 4,096-token prefill as one unit. Ongoing decodes wait across the bracketed gap.","focus":["mono"]},{"title":"Interleave shorter admissions","description":"The lower panel partitions the same prefill into eight 512-token chunks. Each iteration also runs the ongoing decodes.","focus":["chunks"]},{"title":"Compare gaps, not just completion","description":"The triangular markers identify one output token for each ongoing decode. The shorter gaps make the scheduling benefit visible without claiming that prefill work disappeared.","focus":["ticks","mono"]}],"artwork_reviewed":true,"art_sha1":"de7d11f67f9e74ae4bdd8cc8ef3a561973d4f929","art_kind":"svg","art_width":1200,"art_height":640,"art_structural_sha1":"de7d11f67f9e74ae4bdd8cc8ef3a561973d4f929"},"vol3:fig-vol3-circuit-breakers":{"key":"vol3:fig-vol3-circuit-breakers","figure_id":"fig-vol3-circuit-breakers","source":"books/vol3/12_failure_recovery/12_failure_recovery.qmd","title":"Scoped Breaker Transitions","status":"ready","treatment":"annotated","question":"How does a circuit breaker admit one recovery probe while ignoring stale state transitions?","scope":"Thresholds and cooldowns are policy parameters. Probes still require ordinary admission and safe operation contracts; one success does not prove sustained dependency health.","regions":{"closed":{"x":0.06,"y":0.14,"w":0.25,"h":0.14,"label":"CLOSED with ordinary guards"},"trip":{"x":0.31,"y":0.17,"w":0.39,"h":0.08,"label":"Window-count and failure-fraction condition"},"open":{"x":0.695,"y":0.14,"w":0.25,"h":0.14,"label":"OPEN with new calls withheld"},"half":{"x":0.375,"y":0.45,"w":0.25,"h":0.15,"label":"HALF_OPEN single probe slot"},"stale":{"x":0.045,"y":0.8,"w":0.485,"h":0.12,"label":"Late result settles without transition"},"backoff":{"x":0.585,"y":0.76,"w":0.34,"h":0.22,"label":"Bounded cooldown growth"}},"steps":[{"title":"Require enough classified evidence","description":"The transition out of CLOSED requires both the minimum window count and the trip failure fraction. A single failure does not automatically satisfy the displayed condition.","focus":["closed","trip","open"]},{"title":"Claim one probe slot after cooldown","description":"OPEN withholds new calls. When cooldown elapses, the runtime claims the HALF_OPEN probe slot atomically, preventing competing recovery probes.","focus":["open","half"]},{"title":"Fence the current generation","description":"A successful current-generation probe can close the breaker. Failure or timeout reopens it, advances breaker_generation, and lengthens cooldown up to its cap.","focus":["half","closed","backoff"]},{"title":"Settle old results without reopening traffic","description":"A late probe result from an older generation settles in the operation table. It changes no breaker state and cannot override the current generation’s decision.","focus":["stale"]}],"artwork_reviewed":true,"art_sha1":"bb11df96d97f2cb90427705541b9e2335c5f369e","art_kind":"svg","art_width":1200,"art_height":714,"art_structural_sha1":"311b61952ae17e26b4a50525076e9bf4d03ed41b"},"vol3:fig-vol3-collection-pipeline":{"key":"vol3:fig-vol3-collection-pipeline","figure_id":"fig-vol3-collection-pipeline","source":"books/vol3/15_trajectory_curation/15_trajectory_curation.qmd","title":"Collection Credits Across Four Responsibilities","status":"ready","treatment":"annotated","question":"When can a collection run return its credit to the admission pool?","scope":"A credit bounds unsettled collection responsibility, not just active rollout execution. Feedback delay never overrides the hard admission limit.","regions":{"pool":{"x":0.025,"y":0.07,"w":0.235,"h":0.8,"label":"Credit pool, watermark, and hard limit"},"pipeline":{"x":0.255,"y":0.43,"w":0.47,"h":0.18,"label":"Rollout, capture, staging, and assessment"},"held":{"x":0.33,"y":0.68,"w":0.31,"h":0.09,"label":"One credit held per run"},"disposition":{"x":0.75,"y":0.21,"w":0.195,"h":0.61,"label":"Durable disposition or bounded transfer"},"return":{"x":0.035,"y":0.86,"w":0.935,"h":0.075,"label":"Credit-return path"}},"steps":[{"title":"Reserve capacity before rollout","description":"Admission acquires a credit from the pool. The watermark slows dispatch as in-flight work rises, while the hard limit stops admission if feedback arrives too late.","focus":["pool"]},{"title":"Carry responsibility through assessment","description":"The same admitted run keeps its credit through rollout, capture, staging, and assessment. Finishing model execution does not free capacity still needed for the record.","focus":["pipeline","held"]},{"title":"Wait for a durable destination","description":"The record reaches dataset publication, a diagnostic pool, or an unresolved review queue. Transfer to another owner releases responsibility only when that bounded owner acknowledges it.","focus":["disposition"]},{"title":"Return the credit only at the boundary","description":"The dashed return path begins after durable disposition or acknowledged transfer. This keeps capture and assessment backlogs inside the collection capacity bound.","focus":["return","pool"]}],"artwork_reviewed":true,"art_sha1":"9ba8854c289d44895b11b4e13351f322fb30ad3e","art_kind":"svg","art_width":1200,"art_height":470,"art_structural_sha1":"5dccf1edda33046e3077b3f41392550cc82250fa"},"vol3:fig-vol3-context-length-comprehension":{"key":"vol3:fig-vol3-context-length-comprehension","figure_id":"fig-vol3-context-length-comprehension","source":"books/vol3/04_context_engineering/04_context_engineering.qmd","title":"Comprehension Falls with Context Length","status":"ready","treatment":"annotated","question":"Does a larger context allowance preserve comprehension?","scope":"These are measured benchmark curves over the same rewritten stories, not a causal simulation of arbitrary prompts. Length categories are not equally spaced token increments.","regions":{"start":{"x":0.1,"y":0.02,"w":0.23,"h":0.28,"label":"Short-context high accuracy"},"band":{"x":0.2,"y":0.16,"w":0.59,"h":0.34,"label":"Middle-half band through 60k"},"strong":{"x":0.37,"y":0.02,"w":0.59,"h":0.2,"label":"Higher-retention model traces"},"weak":{"x":0.36,"y":0.33,"w":0.43,"h":0.34,"label":"Declining traces through 60k"},"long":{"x":0.77,"y":0.06,"w":0.2,"h":0.41,"label":"Long-context model endpoints"},"legend":{"x":0.11,"y":0.89,"w":0.86,"h":0.1,"label":"Model and cohort legend"}},"steps":[{"title":"Compare like-for-like story questions","description":"At the shortest rewrite many curves begin near the top. Increasing the story length tests retention on the same question set rather than simply admitting a larger request.","focus":["start"]},{"title":"Read the cohort band","description":"The gray middle-half band widens downward through 60k. It summarizes the models scored at every length through that point, not all possible model behavior.","focus":["band","legend"]},{"title":"Inspect the spread between models","description":"Some traces retain high accuracy while others decline substantially. Prompt capacity is therefore different from dependable comprehension of the material inside it.","focus":["strong","weak"]},{"title":"Keep endpoints and uncertainty intact","description":"Only the continuing colored traces provide the displayed evidence at 120k and 192k. Individual wiggles should not be treated as precise threshold locations or interpolated into a universal capacity rule.","focus":["long"]}],"artwork_reviewed":true,"art_sha1":"7660b29fab75a827ca220eb3a404835673741a16","art_kind":"png","art_width":4161,"art_height":2711},"vol3:fig-vol3-context-window-anatomy":{"key":"vol3:fig-vol3-context-window-anatomy","figure_id":"fig-vol3-context-window-anatomy","source":"books/vol3/05_kv_cache/05_kv_cache.qmd","title":"From Agent Context to KV State","status":"ready","treatment":"annotated","question":"Why does a longer context reduce the number of resident trajectories?","scope":"The displayed token counts and KV quantities belong to the figure’s declared architecture; KV cache is not all accelerator memory.","regions":{"prefix":{"x":0.03,"y":0.09,"w":0.43,"h":0.21,"label":"Shared invariant prefix"},"history":{"x":0.46,"y":0.09,"w":0.52,"h":0.21,"label":"Trajectory history and active turn"},"kv":{"x":0.05,"y":0.51,"w":0.43,"h":0.38,"label":"K and V arrays"},"formula":{"x":0.64,"y":0.51,"w":0.34,"h":0.26,"label":"Per-token and per-context KV size"},"pool":{"x":0.64,"y":0.79,"w":0.34,"h":0.18,"label":"Finite KV pool"}},"steps":[{"title":"Separate reusable and growing context","description":"The shared prefix contains system instructions, tool schemas, and workspace content. Turn history and the active observation extend the serialized context.","focus":["prefix","history"]},{"title":"Retain keys and values","description":"Each context token contributes key and value state across the shown heads and layers. The lower arrays depict retained serving state, not a second copy of the prompt text.","focus":["kv"]},{"title":"Scale the footprint","description":"The per-token expression includes both K and V; multiplying by context length gives the context’s KV footprint for this architecture.","focus":["formula"]},{"title":"Capacity becomes concurrency","description":"The finite pool admits only as many contexts as their footprints permit. Increasing context length reduces this capacity even while the model weights stay fixed.","focus":["pool","history"]}],"artwork_reviewed":true,"art_sha1":"b456412bf5672b1a6e552807d713a61bbe62ea7b","art_kind":"svg","art_width":1200,"art_height":900,"art_structural_sha1":"47e358be7bea21ea401ebed0d01e5917e58002ed"},"vol3:fig-vol3-context-zones":{"key":"vol3:fig-vol3-context-zones","figure_id":"fig-vol3-context-zones","source":"books/vol3/04_context_engineering/04_context_engineering.qmd","title":"Reuse Ends at the First Changed Token","status":"ready","treatment":"annotated","question":"Where does prefix reuse stop when the prompt changes?","scope":"Exact token equality and compatible retained cache state are required; semantic similarity is insufficient.","regions":{"zones":{"x":0.18,"y":0.02,"w":0.79,"h":0.16,"label":"Root trunk leaf output zones"},"cold":{"x":0.04,"y":0.24,"w":0.94,"h":0.15,"label":"Cold-start call"},"leaf":{"x":0.04,"y":0.46,"w":0.94,"h":0.16,"label":"Changed leaf"},"trunk":{"x":0.04,"y":0.68,"w":0.94,"h":0.16,"label":"Changed trunk"},"legend":{"x":0.17,"y":0.87,"w":0.7,"h":0.1,"label":"Reuse and processing legend"}},"steps":[{"title":"Organize by change rate","description":"Root instructions change rarely, trunk state changes less often than the latest leaf observation, and output has a separate reserve.","focus":["zones"]},{"title":"Establish the cold prefix","description":"The cold-start call processes root, trunk r17, and leaf n. No previous compatible prefix is reused in this pictured call.","focus":["cold"]},{"title":"Change the leaf","description":"Call n+1 keeps the root and trunk token prefix, so green reuse extends to the first changed leaf token. The later blue portion must be processed.","focus":["leaf","legend"]},{"title":"Refresh the trunk","description":"Call n+2 changes trunk r17 to r18. Reuse now ends after the root even if later content resembles a previous request.","focus":["trunk"]}],"artwork_reviewed":true,"art_sha1":"bd787573eef65c989be1261526fde91ae864eb8c","art_kind":"svg","art_width":1200,"art_height":692,"art_structural_sha1":"9feb5ab65c73c2ad40d51538f43a6d39df42611e"},"vol3:fig-vol3-controlplane-arch":{"key":"vol3:fig-vol3-controlplane-arch","figure_id":"fig-vol3-controlplane-arch","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"The Prototype Loop vs. the Agent Harness","status":"ready","treatment":"annotated","question":"What does a harness add between a model proposal and a tool?","scope":"The diagram compares control boundaries, not two measured implementations.","regions":{"prototype":{"x":0.02,"y":0.03,"w":0.96,"h":0.4,"label":"Direct prototype loop"},"controls":{"x":0.27,"y":0.08,"w":0.38,"h":0.17,"label":"Missing prototype controls"},"harness":{"x":0.33,"y":0.58,"w":0.36,"h":0.4,"label":"Harness-owned records and guards"},"proposal":{"x":0.02,"y":0.72,"w":0.3,"h":0.13,"label":"Model proposes"},"tool":{"x":0.79,"y":0.71,"w":0.19,"h":0.14,"label":"Admitted tool and observation"}},"steps":[{"title":"Locate the direct dispatch","description":"In the prototype loop the model proposal reaches tools at once and the message list holds the state. Pause, spending, and approval have no enforcing boundary.","focus":["prototype","controls"]},{"title":"Insert a guarded transition","description":"The same model now proposes to the harness. The harness owns trajectory records and admits calls through guarded transitions.","focus":["proposal","harness"]},{"title":"Separate control from model inference","description":"Pause, cancellation, spending ceilings, and approval enter the harness independently. Budgets are reserved before work begins.","focus":["harness"]},{"title":"Retain tool outcome ownership","description":"Only an admitted call reaches the tool, whose observation returns through the harness. Tool outcomes and model proposals remain distinct records.","focus":["tool"]}],"artwork_reviewed":true,"art_sha1":"1246ab6c7321919f8dba9a8358f3e3f42607b4e8","art_kind":"svg","art_width":1200,"art_height":853,"art_structural_sha1":"678f6a37fc3db89b7c6e9fbed950866ab6c465eb"},"vol3:fig-vol3-correlated-ensemble-failure":{"key":"vol3:fig-vol3-correlated-ensemble-failure","figure_id":"fig-vol3-correlated-ensemble-failure","source":"books/vol3/18_multi_agent/18_multi_agent.qmd","title":"Majority Review Under an Assumed Error Mixture","status":"ready","treatment":"annotated","question":"Why can more reviewers leave a substantial false-approval floor?","scope":"These curves follow a stipulated beta mixture with fixed marginal error, not a measured law of model ensembles.","regions":{"curves":{"x":0.02,"y":0.06,"w":0.46,"h":0.84,"label":"Independent and beta-mixture majority error"},"floor":{"x":0.08,"y":0.3,"w":0.4,"h":0.17,"label":"Mixture floor and five-reviewer marker"},"zero":{"x":0.61,"y":0.1,"w":0.06,"h":0.8,"label":"Zero approvals among five"},"majority":{"x":0.77,"y":0.1,"w":0.22,"h":0.8,"label":"Three or more approvals among five"}},"steps":[{"title":"Hold individual error fixed","description":"Both curves start with the same reviewer marginal false-approval rate. Independent errors yield rapidly falling majority error as odd reviewer count grows.","focus":["curves"]},{"title":"Shared difficulty leaves a floor","description":"The beta mixture concentrates errors on difficult candidates. Its majority error flattens near the shown probability that latent false-approval propensity exceeds one half.","focus":["floor"]},{"title":"Inspect the count distribution","description":"At five reviewers, the mixture increases both the no-approval extreme and the majority-approval region. More reviewers of the same correlated kind cannot substitute for independent task evidence.","focus":["zero","majority"]}],"artwork_reviewed":true,"art_sha1":"9f83ab546d44de2c492d4d7b7e900fce9748ccd5","art_kind":"svg","art_width":1200,"art_height":584,"art_structural_sha1":"abe106c5fdf6cbead0654a5590ce65ab8f4659f1"},"vol3:fig-vol3-cost-vs-score-long-horizon":{"key":"vol3:fig-vol3-cost-vs-score-long-horizon","figure_id":"fig-vol3-cost-vs-score-long-horizon","source":"books/vol3/19_agent_economics/19_agent_economics.qmd","title":"Cost per Trial Barely Tracks Score","status":"ready","treatment":"annotated","question":"How much does trial price reveal about a long-horizon configuration’s score and repeatability?","scope":"Points are observed configuration means over five trials. Vertical bars are observed worst-to-best ranges, not confidence intervals, and score is not an acceptance probability.","regions":{"low":{"x":0.11,"y":0.58,"w":0.34,"h":0.28,"label":"Lower-cost configurations and labels"},"middle":{"x":0.47,"y":0.11,"w":0.19,"h":0.66,"label":"Similar-price configurations around the middle"},"leaders":{"x":0.47,"y":0.08,"w":0.1,"h":0.28,"label":"High-scoring configurations with overlapping ranges"},"expensive":{"x":0.8,"y":0.07,"w":0.18,"h":0.24,"label":"Highest-price labeled point"},"ranges":{"x":0.56,"y":0.18,"w":0.1,"h":0.47,"label":"Observed trial ranges"},"axis":{"x":0.08,"y":0.87,"w":0.89,"h":0.11,"label":"Logarithmic trial-cost axis"}},"steps":[{"title":"Read a configuration, not a purchase guarantee","description":"Each dot is a configuration’s mean score, and parenthesized labels show average trial hours. The horizontal axis measures the average cost of one trial on a logarithmic scale.","focus":["low","axis"]},{"title":"Compare scores at similar prices","description":"The middle cost band contains configurations with widely separated mean scores. Spending a similar amount does not imply obtaining a similar result.","focus":["middle"]},{"title":"Retain the variation across trials","description":"The light bars span the worst and best of five trials. Their overlap and width show observed variability; they are not statistical confidence intervals around the means.","focus":["ranges","leaders"]},{"title":"Assess the expensive increment","description":"The far-right labeled configuration has the highest mean, while near-leading means appear much farther left. This measured comparison motivates routing analysis without proving that a price increase causes a score increase.","focus":["expensive","leaders"]}],"artwork_reviewed":true,"art_sha1":"33dac8c3ae2b06b48c58e7a8bd81cff1de30b9b1","art_kind":"png","art_width":4115,"art_height":2636},"vol3:fig-vol3-coverage-vs-selection":{"key":"vol3:fig-vol3-coverage-vs-selection","figure_id":"fig-vol3-coverage-vs-selection","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Availability Outruns Selection","status":"ready","treatment":"annotated","question":"Why can a larger candidate pool contain better answers without improving the answer returned?","scope":"Curves are recomputed from released per-sample labels. Repository repair and competition mathematics are different tasks; their coverage curves are not a controlled model comparison.","regions":{"legend":{"x":0.68,"y":0.64,"w":0.28,"h":0.2,"label":"Coverage, vote, and repair legend"},"early":{"x":0.08,"y":0.22,"w":0.29,"h":0.45,"label":"Small-pool growth"},"coverage":{"x":0.37,"y":0.03,"w":0.58,"h":0.19,"label":"Continuing coverage growth"},"vote":{"x":0.44,"y":0.34,"w":0.52,"h":0.2,"label":"Majority-vote plateaus"},"repair":{"x":0.08,"y":0.39,"w":0.53,"h":0.38,"label":"Test-checked repair coverage"},"axis":{"x":0.07,"y":0.86,"w":0.89,"h":0.12,"label":"Logarithmic pool-size axis"}},"steps":[{"title":"Separate availability from selection","description":"Solid mathematical curves measure pools containing a correct candidate. Dashed curves measure answers actually returned by majority voting over those pools.","focus":["legend","early"]},{"title":"More available answers do not force better votes","description":"Coverage continues climbing while majority voting flattens. A selector returning an unchanged pool member cannot exploit a correct candidate it fails to recognize.","focus":["coverage","vote"]},{"title":"Give the selector usable evidence","description":"The dotted repair curve measures coverage under tests. Its availability is useful only insofar as the tests identify candidates satisfying their tested predicate, which remains narrower than complete task acceptance.","focus":["repair"]},{"title":"Compare on the recorded sample range","description":"The pool-size axis is logarithmic. The repair series ends much earlier than the mathematical series; the absent continuation is not an invitation to extrapolate it.","focus":["axis","repair"]}],"artwork_reviewed":true,"art_sha1":"76d725d18397e5810dd5363257430ed370edc544","art_kind":"png","art_width":4215,"art_height":2512},"vol3:fig-vol3-credit-assignment":{"key":"vol3:fig-vol3-credit-assignment","figure_id":"fig-vol3-credit-assignment","source":"books/vol3/17_rlvr/17_rlvr.qmd","title":"Three Ways to Connect a Terminal Outcome to Earlier Turns","status":"ready","treatment":"annotated","question":"What does each feedback scheme actually establish about an earlier turn?","scope":"The fork outcomes are hypothetical sampling evidence. Their difference is not a causal proof; learned step scores change the optimized criterion.","regions":{"terminal":{"x":0.02,"y":0.02,"w":0.96,"h":0.25,"label":"Terminal-only returns"},"learned":{"x":0.02,"y":0.32,"w":0.96,"h":0.28,"label":"Learned step-score feedback"},"forks":{"x":0.02,"y":0.68,"w":0.49,"h":0.24,"label":"Continuation samples at two forks"},"estimate":{"x":0.02,"y":0.91,"w":0.96,"h":0.08,"label":"Estimated values, difference, uncertainty"}},"steps":[{"title":"One terminal failure cannot separate turns","description":"The debugger action and faulty edit lead to the same failed terminal check. With only that check, each shown reward-to-go chip receives the same outcome.","focus":["terminal"]},{"title":"Intermediate scores add a criterion","description":"The learned scorer supplies per-step scores, but those scores are an added objective. A policy can satisfy the scorer without making task progress.","focus":["learned"]},{"title":"Sample continuations from each fork","description":"The bottom panel restores two fork conditions and samples 20 continuations each. One passes from h0 and twelve pass from h1.","focus":["forks"]},{"title":"Keep estimation uncertainty visible","description":"The displayed means differ by 0.55, with sampling error. This estimates a difference under the stated continuation procedure and does not establish that the debugger caused success.","focus":["estimate"]}],"artwork_reviewed":true,"art_sha1":"603270a67f0316e6ffac0a5c9e459b2fe9800f26","art_kind":"svg","art_width":1200,"art_height":1024,"art_structural_sha1":"c58674036e3f6ddbbd57779a155f4c601e278e69"},"vol3:fig-vol3-critical-path-waterfall":{"key":"vol3:fig-vol3-critical-path-waterfall","figure_id":"fig-vol3-critical-path-waterfall","source":"books/vol3/19_agent_economics/19_agent_economics.qmd","title":"Faster Model Calls, a Barely Shorter Episode","status":"ready","treatment":"annotated","question":"Why can much faster model calls barely shorten this serial repair episode?","scope":"Bars are disjoint category totals, not a chronological trace. The speculative-decode estimate assumes negligible nondecode time within the model intervals.","regions":{"tests":{"x":0.03,"y":0.19,"w":0.61,"h":0.64,"label":"Unchanged required-test subtotal"},"sandbox":{"x":0.64,"y":0.19,"w":0.1,"h":0.64,"label":"Unchanged sandbox lifecycle subtotal"},"model":{"x":0.735,"y":0.19,"w":0.08,"h":0.64,"label":"Model-call segments and removed time"},"floor":{"x":0.72,"y":0.1,"w":0.03,"h":0.73,"label":"Non-model floor"},"axis":{"x":0.02,"y":0.84,"w":0.8,"h":0.13,"label":"Shared elapsed-time axis"},"results":{"x":0.82,"y":0.19,"w":0.17,"h":0.64,"label":"Episode totals and speedups"}},"steps":[{"title":"Identify the dominant baseline work","description":"Required tests occupy most of the baseline episode, followed by sandbox lifecycle work. The model-call segment is the small remaining blue portion.","focus":["tests","sandbox","model"]},{"title":"Accelerate only the model segment","description":"The four-times-faster and speculative-decode cases shrink the blue segment while tests and lifecycle work retain their widths. Dashed outlines show removed model time on the same scale.","focus":["model","results"]},{"title":"Find the absolute bound","description":"Instant model calls remove the remaining blue segment but stop at the dashed non-model floor. Improving a small fraction of episode work cannot eliminate the larger fixed subtotal.","focus":["floor","sandbox"]},{"title":"Read these bars as category sums","description":"The shared elapsed-time axis makes total durations comparable. Segment order groups categories for accounting; it does not claim tests all happened before every model call.","focus":["axis","tests"]}],"artwork_reviewed":true,"art_sha1":"fb2e1d444b16e15d782a46a1466c6739a6ae244d","art_kind":"svg","art_width":1200,"art_height":608,"art_structural_sha1":"ae105c9df20917c57cb632b1417cb52591a333fc"},"vol3:fig-vol3-deep-vs-shallow-interface":{"key":"vol3:fig-vol3-deep-vs-shallow-interface","figure_id":"fig-vol3-deep-vs-shallow-interface","source":"books/vol3/07_tool_calling/07_tool_calling.qmd","title":"Shallow and deep interfaces for one edit","status":"ready","treatment":"annotated","question":"What state leaves the trajectory when a low-level edit sequence becomes a task-level operation?","scope":"A one-call interface does not itself guarantee atomicity. The implementation must supply all-or-nothing behavior or report partial effects accurately.","regions":{"calls":{"x":0.15,"y":0.09,"w":0.78,"h":0.15,"label":"Four low-level model calls and state"},"tools":{"x":0.14,"y":0.32,"w":0.8,"h":0.13,"label":"Open, seek, write, and close"},"task":{"x":0.155,"y":0.58,"w":0.135,"h":0.11,"label":"One task-level model call"},"implementation":{"x":0.14,"y":0.785,"w":0.75,"h":0.17,"label":"Version check and change behind interface"},"returns":{"x":0.32,"y":0.58,"w":0.47,"h":0.11,"label":"Conflict or diff with new version"}},"steps":[{"title":"Expose low-level obligations","description":"The top trajectory carries a handle, cursor, and cleanup across four model calls. Each call must preserve the state required by the next operation.","focus":["calls","tools"]},{"title":"Move the operation behind the interface","description":"The lower trajectory invokes apply_patch once. The tool implementation owns the version check and applies the change behind that boundary.","focus":["task","implementation"]},{"title":"Return a meaningful outcome","description":"A version mismatch returns a conflict; a successful change returns a diff and new version. The deeper interface relocates coordination obligations rather than removing them.","focus":["returns","implementation"]}],"artwork_reviewed":true,"art_sha1":"10334fba6088e2571375c543dc7276923454593a","art_kind":"svg","art_width":1200,"art_height":676,"art_structural_sha1":"6be6f7edfac13b49bf633c0d3384a15ec527db6a"},"vol3:fig-vol3-diagnostic-tree":{"key":"vol3:fig-vol3-diagnostic-tree","figure_id":"fig-vol3-diagnostic-tree","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Committing to a Hypothesis vs. Checking It","status":"ready","treatment":"annotated","question":"Why does a short diagnostic test change the repair before the first edit?","scope":"The passing reproducer covers the tested condition; it does not establish full task acceptance or all thread interleavings.","regions":{"failure":{"x":0.285,"y":0.03,"w":0.385,"h":0.09,"label":"Observed connection-pool failure"},"commit":{"x":0.045,"y":0.22,"w":0.435,"h":0.13,"label":"Commit-first hypotheses"},"test":{"x":0.525,"y":0.39,"w":0.435,"h":0.1,"label":"Targeted waiter-return test"},"revised":{"x":0.525,"y":0.52,"w":0.435,"h":0.13,"label":"Contradicted timeout hypothesis"},"edit":{"x":0.025,"y":0.67,"w":0.94,"h":0.17,"label":"First-edit boundary and patches"},"outcomes":{"x":0.045,"y":0.87,"w":0.915,"h":0.1,"label":"Different outcomes"}},"steps":[{"title":"Keep both explanations open","description":"A request still waits after a connection becomes free. A short timeout and a missed notification are competing explanations of the same symptom.","focus":["failure","commit"]},{"title":"Ask an observation to separate them","description":"The targeted test orders a waiting worker and a returning connection. The waiter stays blocked after return, contradicting the timeout explanation in this case.","focus":["test","revised"]},{"title":"Delay the edit until evidence arrives","description":"The dashed first-edit boundary shows the difference: the commit-first path edits without a distinguishing check, while the check-first path revises its diagnosis first.","focus":["edit"]},{"title":"Separate reproducer success from acceptance","description":"The unchecked timeout patch can mask the symptom while leaving the defect. The notification patch passes the reproducer, but acceptance remains pending.","focus":["outcomes"]}],"artwork_reviewed":true,"art_sha1":"2253a64cf0fa877c8d1944398e75026308318921","art_kind":"svg","art_width":1200,"art_height":932,"art_structural_sha1":"4d33d38fcd189a4b02dbd341c827847d45a87718"},"vol3:fig-vol3-epistemic-attractor-cycle":{"key":"vol3:fig-vol3-epistemic-attractor-cycle","figure_id":"fig-vol3-epistemic-attractor-cycle","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"A Runaway Loop and the Budget That Ends It","status":"ready","treatment":"annotated","question":"Why are valid individual calls insufficient to bound a failing trajectory?","scope":"The loop is an illustrative failure pattern; the harness budget is maintained outside model context.","regions":{"cycle":{"x":0.07,"y":0.05,"w":0.39,"h":0.55,"label":"Retry failure cycle"},"context":{"x":0.52,"y":0.03,"w":0.46,"h":0.38,"label":"Accumulating errors in context"},"budget":{"x":0.02,"y":0.72,"w":0.59,"h":0.24,"label":"Actual reserved proposed and finalization budget"},"stop":{"x":0.62,"y":0.74,"w":0.36,"h":0.18,"label":"Admission refusal and finalization"}},"steps":[{"title":"Follow a locally valid failure loop","description":"The model proposes a variant, the test fails, and the error is appended before another retry. Each call may be well formed and within its individual limits.","focus":["cycle"]},{"title":"Observe history without progress","description":"Later contexts carry more error observations while the original task remains. A growing transcript alone supplies no termination guarantee.","focus":["context"]},{"title":"Account outside the prompt","description":"The harness sums actual, reserved, proposed, and finalization resources against the allowance. Model-visible history is not the authoritative budget ledger.","focus":["budget"]},{"title":"Refuse new work at the boundary","description":"When the proposed admission exceeds the budget or deadline, the harness routes to FINALIZING to settle or transfer obligations. Refusal does not erase work already dispatched.","focus":["stop"]}],"artwork_reviewed":true,"art_sha1":"1c42c015f80aa4cb638d8e1142953b8303bef67c","art_kind":"svg","art_width":1200,"art_height":664,"art_structural_sha1":"85799b654f0c28710baddb86f2608af9d0484b82"},"vol3:fig-vol3-eval-gym-architecture":{"key":"vol3:fig-vol3-eval-gym-architecture","figure_id":"fig-vol3-eval-gym-architecture","source":"books/vol3/13_evaluation/13_evaluation.qmd","title":"Trial Sandbox and Grading Boundary","status":"ready","treatment":"annotated","question":"How can an evaluation trial test a candidate without letting it alter the grader?","scope":"The sandbox contains the candidate’s trial state; trusted grading criteria and verdict handling remain outside its reach.","regions":{"trial":{"x":0.02,"y":0.04,"w":0.43,"h":0.91,"label":"Per-trial sandbox"},"writes":{"x":0.07,"y":0.31,"w":0.37,"h":0.33,"label":"Copy-on-write workspace and base"},"grader":{"x":0.58,"y":0.15,"w":0.37,"h":0.28,"label":"Trusted grading controller"},"candidate":{"x":0.58,"y":0.55,"w":0.37,"h":0.2,"label":"Limited candidate execution"},"verdict":{"x":0.58,"y":0.82,"w":0.37,"h":0.13,"label":"Verdicts bound to workspace"}},"steps":[{"title":"Isolate each trial’s writes","description":"The agent under test edits a copy-on-write layer over a read-only base image. Service fixtures supply controlled interactions; external egress is blocked.","focus":["trial","writes"]},{"title":"Protect acceptance criteria","description":"Held-out tests, criteria, and results stay in the trusted controller. The candidate may produce untrusted output but cannot rewrite the grading contract.","focus":["grader","candidate"]},{"title":"Bind evidence to the tested workspace","description":"The selected workspace ws_r19 reaches candidate execution. Pass, fail, pending, or unknown verdicts remain bound to that workspace rather than to the agent’s own success claim.","focus":["candidate","verdict"]}],"artwork_reviewed":true,"art_sha1":"4fee6fd60d2dba94a5487db02bd6c4bc991beb10","art_kind":"svg","art_width":1200,"art_height":725,"art_structural_sha1":"1b7e6589072ae4edeb293c412805adc57f502916"},"vol3:fig-vol3-event-sourcing":{"key":"vol3:fig-vol3-event-sourcing","figure_id":"fig-vol3-event-sourcing","source":"books/vol3/11_durable_execution/11_durable_execution.qmd","title":"The Trajectory Record as a Projection of the Log","status":"ready","treatment":"annotated","question":"What can a durable log reconstruct after runtime memory is lost?","scope":"Reconstruction folds recorded events only; it does not rerun model or tool calls, and a missing result remains unresolved.","regions":{"initial":{"x":0.02,"y":0.14,"w":0.27,"h":0.3,"label":"Initial record"},"reducer":{"x":0.36,"y":0.14,"w":0.27,"h":0.3,"label":"Deterministic reducer"},"record":{"x":0.73,"y":0.14,"w":0.25,"h":0.3,"label":"Reconstructed record"},"log":{"x":0.02,"y":0.61,"w":0.76,"h":0.32,"label":"Durable ordered log"},"missing":{"x":0.8,"y":0.71,"w":0.18,"h":0.22,"label":"Unrecorded tool result"}},"steps":[{"title":"Recover from durable events","description":"The bottom log retains ordered events after the top runtime memory is lost. TaskStarted through ToolIntent establish what was recorded before the crash boundary.","focus":["log"]},{"title":"Fold without effects","description":"The deterministic reducer applies each event to the initial record. It makes no new model call or tool call during reconstruction.","focus":["initial","reducer"]},{"title":"Preserve uncertainty","description":"The reconstructed record retains admission and reservation state but marks test_r18 unresolved. A ToolResult beyond the recorded boundary cannot be invented from the intent.","focus":["record","missing"]}],"artwork_reviewed":true,"art_sha1":"c7cff7b79b3d600be315c1ad35877b56ca7cb10e","art_kind":"svg","art_width":1200,"art_height":585,"art_structural_sha1":"7727e545a10056087acf302176b997a4cc9867d7"},"vol3:fig-vol3-exfiltration-conjunction":{"key":"vol3:fig-vol3-exfiltration-conjunction","figure_id":"fig-vol3-exfiltration-conjunction","source":"books/vol3/09_security/09_security.qmd","title":"Three Connections on One Disclosure Path","status":"ready","treatment":"annotated","question":"Which connections must coexist for this injection-driven fixture disclosure path?","scope":"The conjunction describes this particular disclosure path, not every leak or harm. Quarantine narrows exposure rather than proving complete elimination.","regions":{"private":{"x":0.02,"y":0.3,"w":0.16,"h":0.22,"label":"Private fixture and data reach"},"content":{"x":0.32,"y":0.18,"w":0.17,"h":0.29,"label":"Attacker-controlled content connection"},"outbound":{"x":0.49,"y":0.18,"w":0.19,"h":0.29,"label":"Outbound recipient connection"},"mitigations":{"x":0.17,"y":0.6,"w":0.5,"h":0.32,"label":"Three boundary interventions"},"policy":{"x":0.66,"y":0.25,"w":0.16,"h":0.35,"label":"Dependency and recipient check"},"disclosure":{"x":0.85,"y":0.3,"w":0.13,"h":0.22,"label":"Disclosure at service"}},"steps":[{"title":"Start with the reachable private data","description":"The path begins at the private fixture. A protected runner can return a test result without returning the fixture’s bytes, weakening the private-data connection.","focus":["private","mitigations"]},{"title":"Trace influence toward an outbound recipient","description":"The path also needs attacker-controlled content and a reachable outbound service. The quarantined reader and egress boundary address different connections.","focus":["content","outbound","mitigations"]},{"title":"Enforce the combined release decision","description":"When useful work still needs all three connections, the pre-dispatch dependency and recipient check decides whether the query may leave. Ordinary access to a service is not sufficient release authority.","focus":["policy","disclosure"]}],"artwork_reviewed":true,"art_sha1":"bed0533e8b8cc307e40662be254a92c64b1edcd3","art_kind":"svg","art_width":1200,"art_height":435,"art_structural_sha1":"f06ed26f192e48d96cb71a707b16500f52c964ff"},"vol3:fig-vol3-exposure-bias-dagger":{"key":"vol3:fig-vol3-exposure-bias-dagger","figure_id":"fig-vol3-exposure-bias-dagger","source":"books/vol3/16_fine_tuning/16_fine_tuning.qmd","title":"Exposure Bias and On-Policy Labeling","status":"ready","treatment":"annotated","question":"How does on-policy labeling address states missing from reference demonstrations?","scope":"The displayed bounds retain their distinct error distributions and bounded-disadvantage assumption; aggregation alone does not equalize distributions.","regions":{"reference":{"x":0.04,"y":0.05,"w":0.61,"h":0.22,"label":"Reference-state corpus"},"deviation":{"x":0.15,"y":0.25,"w":0.42,"h":0.2,"label":"Unlabeled learner deviation"},"collect":{"x":0.03,"y":0.61,"w":0.44,"h":0.13,"label":"Run collect and propose"},"verify":{"x":0.5,"y":0.61,"w":0.13,"h":0.22,"label":"Sandbox verification and discard"},"update":{"x":0.66,"y":0.61,"w":0.31,"h":0.13,"label":"Aggregate and retrain"},"fault":{"x":0.03,"y":0.82,"w":0.43,"h":0.12,"label":"Fault record masks"},"bounds":{"x":0.65,"y":0.8,"w":0.33,"h":0.16,"label":"Qualified learner-state bound"}},"steps":[{"title":"Locate the coverage gap","description":"The learner leaves the recorded reference path at s2. Subsequent dashed red states have no recorded correction even if imitation error on reference states is small.","focus":["reference","deviation"]},{"title":"Collect states the current policy visits","description":"A labeling round runs the current policy with the stated reference mixture, records visited states, and obtains proposed corrective labels.","focus":["collect"]},{"title":"Verify before retaining a label","description":"A sandbox continuation must pass the verifier before aggregation. Rejected proposals follow the discard path rather than entering training merely because a labeler produced them.","focus":["verify","update"]},{"title":"Select recovery rather than injected error","description":"In the fault-injected record, the error has mask zero; diagnosis and corrective call have mask one. Retraining broadens coverage, while the learner-state bound still requires its printed assumptions.","focus":["fault","bounds"]}],"artwork_reviewed":true,"art_sha1":"bf553fec9c4046b5288efd9050bcee6c7271ba20","art_kind":"svg","art_width":1200,"art_height":848,"art_structural_sha1":"de42bd11b1d47a0835a4b1dfb1a71787338416f2"},"vol3:fig-vol3-failure-diagnostic-tree":{"key":"vol3:fig-vol3-failure-diagnostic-tree","figure_id":"fig-vol3-failure-diagnostic-tree","source":"books/vol3/15_trajectory_curation/15_trajectory_curation.qmd","title":"Probes Before Weights","status":"ready","treatment":"annotated","question":"When should a measured agent failure lead to a systems repair rather than a weight update?","scope":"The ladder is the default diagnostic route. A resolving probe supports a scoped repair, not exclusive causality; weight changes require residual behavioral evidence.","regions":{"failure":{"x":0.155,"y":0.025,"w":0.31,"h":0.095,"label":"Measured failing trace"},"context":{"x":0.155,"y":0.17,"w":0.31,"h":0.09,"label":"Context probe"},"schema":{"x":0.155,"y":0.31,"w":0.31,"h":0.09,"label":"Schema probe"},"runtime":{"x":0.155,"y":0.45,"w":0.31,"h":0.09,"label":"Runtime probe"},"repairs":{"x":0.61,"y":0.17,"w":0.37,"h":0.37,"label":"Reversible systems repairs"},"residual":{"x":0.155,"y":0.66,"w":0.31,"h":0.09,"label":"Residual failure"},"learning":{"x":0.61,"y":0.66,"w":0.37,"h":0.23,"label":"Fine-tuning before reinforcement learning"}},"steps":[{"title":"Supply the missing fact first","description":"The context probe tests whether supplying missing information makes the measured failure disappear. If it does, the immediate repair targets retrieval or assembly.","focus":["failure","context","repairs"]},{"title":"Test interface and runtime conditions","description":"Persisting failures proceed through corrected tool descriptions and a clean sandbox with raised limits. Disappearing failures route to the corresponding schema or runtime repair.","focus":["schema","runtime","repairs"]},{"title":"Isolate the residual before training","description":"Only a failure surviving every lower-rung probe reaches the residual behavioral branch. These probes target cheaper, more reversible interventions before weight modification.","focus":["residual"]},{"title":"Sequence weight changes behind evidence","description":"The default route tries supervised fine-tuning on a curated residual corpus before reinforcement learning with protected reward checks. The diagram does not make either update an automatic cure.","focus":["learning"]}],"artwork_reviewed":true,"art_sha1":"4726ae4dd05c3d47978501fe3865e50762102d74","art_kind":"svg","art_width":1200,"art_height":1006,"art_structural_sha1":"7f1fcd58c4671682c18d199bab680ff3b9439587"},"vol3:fig-vol3-goodhart-divergence":{"key":"vol3:fig-vol3-goodhart-divergence","figure_id":"fig-vol3-goodhart-divergence","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Proxy and Reference Scores under Selection","status":"ready","treatment":"annotated","question":"What does a growing gap between the selected candidate’s proxy and reference scores reveal?","scope":"This is a qualitative empirical sketch without numerical axis values. A reference-score downturn depends on the task and is not implied by scoring error alone.","regions":{"initial":{"x":0.1,"y":0.38,"w":0.3,"h":0.48,"label":"Initially rising scores"},"turn":{"x":0.42,"y":0.32,"w":0.18,"h":0.39,"label":"Reference-score turning region"},"gap":{"x":0.71,"y":0.15,"w":0.2,"h":0.47,"label":"Proxy-reference gap"}},"steps":[{"title":"Both scores can improve initially","description":"At smaller candidate pools, the selected candidate improves on both the proxy and the held-out reference. Pool size runs along a logarithmic horizontal axis.","focus":["initial"]},{"title":"The reference can stop improving","description":"The green reference curve peaks while the dashed proxy continues upward. The turning location is task-dependent, so the sketch supplies no universal stopping threshold.","focus":["turn"]},{"title":"Selection can amplify proxy optimism","description":"The red bracket marks the widening disagreement at larger pools. A higher selected proxy score therefore needs an independent reference check; it is not sufficient evidence of higher task utility.","focus":["gap"]}],"artwork_reviewed":true,"art_sha1":"d020229226d7b5cfb55809674fa43fb738ba9d0b","art_kind":"svg","art_width":1200,"art_height":519,"art_structural_sha1":"00db9dd574a387814c6f28106515d7fa3fbd7009"},"vol3:fig-vol3-grammar-constrained-fsm":{"key":"vol3:fig-vol3-grammar-constrained-fsm","figure_id":"fig-vol3-grammar-constrained-fsm","source":"books/vol3/02_foundation_model/02_foundation_model.qmd","title":"Grammar-Constrained Decoding","status":"ready","treatment":"annotated","question":"How does a grammar mask restrict the next sampled token?","scope":"This query-tool automaton enforces syntax; it does not establish data truth or authorization.","regions":{"schema":{"x":0.02,"y":0.1,"w":0.27,"h":0.2,"label":"Schema compilation"},"states":{"x":0.36,"y":0.03,"w":0.62,"h":0.29,"label":"Parser states and masks"},"raw":{"x":0.02,"y":0.46,"w":0.32,"h":0.39,"label":"Unmasked logits"},"masked":{"x":0.45,"y":0.46,"w":0.32,"h":0.39,"label":"Masked logits"},"sample":{"x":0.85,"y":0.62,"w":0.12,"h":0.17,"label":"Sample and advance"},"limits":{"x":0.02,"y":0.88,"w":0.96,"h":0.08,"label":"Properties not checked"}},"steps":[{"title":"Compile the tool language","description":"The schema is compiled once into parser states with associated vocabulary masks. The current state selects the mask used at this decode step.","focus":["schema","states"]},{"title":"Remove illegal continuations","description":"The raw logits include fluent but invalid alternatives. Adding the state mask assigns invalid entries negative infinity before sampling.","focus":["raw","masked"]},{"title":"Advance after sampling","description":"The pictured opening brace is sampled from the legal support and advances the parser to q1. The next token uses that new state.","focus":["sample","states"]},{"title":"Respect the guarantee boundary","description":"A grammatical query can still name a nonexistent table, use incorrect values, or be unauthorized. Those checks remain outside the token mask.","focus":["limits"]}],"artwork_reviewed":true,"art_sha1":"03d58d8b360fb69aaeda0dab62a0c988abb3ff2a","art_kind":"svg","art_width":1200,"art_height":784,"art_structural_sha1":"cb8b7d0a79c70d9a4c11696609aa96b1f2fabb49"},"vol3:fig-vol3-harness-trajectory-states":{"key":"vol3:fig-vol3-harness-trajectory-states","figure_id":"fig-vol3-harness-trajectory-states","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"Trajectory State Machine","status":"ready","treatment":"annotated","question":"Why does stopping admission differ from completing a trajectory?","scope":"This is the chapter’s abstract trajectory state machine; FINALIZING settles or transfers remaining obligations.","regions":{"ready":{"x":0.04,"y":0.34,"w":0.29,"h":0.15,"label":"READY admission"},"model":{"x":0.4,"y":0.34,"w":0.23,"h":0.15,"label":"Reserved model call"},"wait":{"x":0.07,"y":0.62,"w":0.23,"h":0.16,"label":"Running tool wait"},"approval":{"x":0.4,"y":0.62,"w":0.23,"h":0.16,"label":"Held approval"},"pause":{"x":0.07,"y":0.07,"w":0.23,"h":0.16,"label":"Paused live state"},"final":{"x":0.72,"y":0.34,"w":0.23,"h":0.15,"label":"Finalizing"},"terminal":{"x":0.77,"y":0.55,"w":0.21,"h":0.41,"label":"Absorbing outcomes"}},"steps":[{"title":"Admit from READY","description":"READY checks current guards before reserving a model call. A previous scheduling decision does not authorize later work automatically.","focus":["ready","model"]},{"title":"Represent external waits","description":"WAITING_TOOL tracks an admitted tool operation; AWAITING_APPROVAL holds a proposal before dispatch. Approved work still requires guards to pass.","focus":["wait","approval"]},{"title":"Pause without finalizing","description":"PAUSED admits no new work but remains a live state with a resume path. It is distinct from a completed or canceled result.","focus":["pause","ready"]},{"title":"Stop admission and settle","description":"Completion, cancellation, deadlines, and budget limits route through FINALIZING. Only after checks and settlement does the trajectory enter an absorbing outcome.","focus":["final","terminal"]}],"artwork_reviewed":true,"art_sha1":"2d609263bf22e60adf555f5f79bedabf09ef56c2","art_kind":"svg","art_width":1200,"art_height":723,"art_structural_sha1":"571bf2da26096485666b069a9de9ff72e5dcc0dd"},"vol3:fig-vol3-hierarchical-revision":{"key":"vol3:fig-vol3-hierarchical-revision","figure_id":"fig-vol3-hierarchical-revision","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Choosing the Revision Scope","status":"ready","treatment":"annotated","question":"How much of a candidate should change when new evidence removes support?","scope":"The decision classifies the lost support. It does not establish an unconditional preference for the smallest edit, and stopping leaves an unresolved task.","regions":{"evidence":{"x":0.01,"y":0.01,"w":0.35,"h":0.13,"label":"New evidence"},"dependent":{"x":0.04,"y":0.18,"w":0.32,"h":0.22,"label":"Dependents’ needs"},"premises":{"x":0.38,"y":0.18,"w":0.31,"h":0.22,"label":"Task premises"},"local":{"x":0.03,"y":0.5,"w":0.3,"h":0.35,"label":"Local repair"},"subgraph":{"x":0.36,"y":0.5,"w":0.3,"h":0.35,"label":"Subgraph resynthesis"},"stop":{"x":0.69,"y":0.5,"w":0.3,"h":0.35,"label":"Stop deliberation"}},"steps":[{"title":"Test what the dependents still need","description":"The first diamond asks whether dependents still have the support they require. A yes permits replacing one artifact while retaining its descendants.","focus":["evidence","dependent","local"]},{"title":"Expand scope when dependencies fail","description":"If dependents lose support but the task premises remain valid, subgraph resynthesis replaces the artifact and its descendants together.","focus":["premises","subgraph"]},{"title":"Stop when the task premise fails","description":"A failed premise leads to stopping deliberation and reporting unresolved or escalating. A small local edit cannot repair an invalid task premise.","focus":["premises","stop"]}],"artwork_reviewed":true,"art_sha1":"386ddda2836f04f8e550784e30a2eb35f8bb416c","art_kind":"svg","art_width":1200,"art_height":648,"art_structural_sha1":"f91d07b27d5db31714ba1dcb0995b326959575f9"},"vol3:fig-vol3-hnsw-routing":{"key":"vol3:fig-vol3-hnsw-routing","figure_id":"fig-vol3-hnsw-routing","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"Searching an HNSW Graph","status":"ready","treatment":"annotated","question":"How does HNSW reach candidates without scanning every stored vector?","scope":"The route is schematic; visited candidates and returned neighbors differ, and approximate search can miss true neighbors.","regions":{"upper":{"x":0.04,"y":0.02,"w":0.94,"h":0.25,"label":"Sparse upper layer"},"middle":{"x":0.04,"y":0.32,"w":0.94,"h":0.24,"label":"Intermediate greedy route"},"base":{"x":0.04,"y":0.63,"w":0.94,"h":0.25,"label":"Layer-zero beam"},"returned":{"x":0.65,"y":0.67,"w":0.23,"h":0.17,"label":"Returned best k"},"legend":{"x":0.04,"y":0.91,"w":0.94,"h":0.06,"label":"Traversal legend"}},"steps":[{"title":"Enter the sparse hierarchy","description":"The upper-layer entry point starts a greedy walk toward q. When no closer neighbor is available, the search drops to the matching node below.","focus":["upper"]},{"title":"Refine the route","description":"The intermediate layer provides more vectors and another greedy hop. The dashed drop leads to the starting point for the base-layer beam.","focus":["middle"]},{"title":"Explore a bounded candidate set","description":"Layer zero contains every vector, but the beam visits only part of the graph. efSearch controls exploration rather than making all nodes visible.","focus":["base"]},{"title":"Return from visited candidates","description":"Filled green nodes mark the returned best k; outlined green nodes were visited but not returned. Unvisited nodes cannot enter this result.","focus":["returned","legend"]}],"artwork_reviewed":true,"art_sha1":"9e41f7b86a0b25c20aeb52c0cf3f4c075611c7e1","art_kind":"svg","art_width":1200,"art_height":794,"art_structural_sha1":"3d359bb17fd4ff30b24aaae5d54077338a8333d1"},"vol3:fig-vol3-hnsw-rrf":{"key":"vol3:fig-vol3-hnsw-rrf","figure_id":"fig-vol3-hnsw-rrf","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"From Candidate Lists to Staged Evidence","status":"ready","treatment":"annotated","question":"How do lexical and dense retrieval combine without comparing incompatible scores?","scope":"Fusion uses ranks over matched evidence identities; reranking remains bounded and does not establish truth.","regions":{"ranks":{"x":0.17,"y":0.07,"w":0.17,"h":0.76,"label":"Separate ranked lists"},"identity":{"x":0.38,"y":0.06,"w":0.27,"h":0.19,"label":"Identity join"},"fusion":{"x":0.38,"y":0.27,"w":0.27,"h":0.63,"label":"Reciprocal rank scores"},"rerank":{"x":0.7,"y":0.37,"w":0.16,"h":0.34,"label":"Short pool cross-encoder"},"stage":{"x":0.88,"y":0.32,"w":0.1,"h":0.44,"label":"Revision-bound staged items"}},"steps":[{"title":"Generate complementary candidate lists","description":"Lexical ranking places B first while dense ranking places C first. Their raw scores need not share a numerical scale.","focus":["ranks"]},{"title":"Join the same evidence identity","description":"Scope, path, version, and span define a match. A span from r17 is not the same evidence item as an r18 span.","focus":["identity"]},{"title":"Add rank contributions","description":"A appears in both lists and receives two reciprocal-rank contributions. Fusion rewards cross-list support without treating lexical and dense scores as interchangeable.","focus":["fusion"]},{"title":"Rerank a short pool","description":"The cross-encoder evaluates a bounded shortlist before staging evidence. Its work grows with pool size and pair length, so the shortlist is also a resource boundary.","focus":["rerank","stage"]}],"artwork_reviewed":true,"art_sha1":"398541d69cbc99b70534967953e7939771f51f96","art_kind":"svg","art_width":1200,"art_height":527,"art_structural_sha1":"f1a7b41da36b52862325c952faf577dce96875d4"},"vol3:fig-vol3-hsa-taxonomy":{"key":"vol3:fig-vol3-hsa-taxonomy","figure_id":"fig-vol3-hsa-taxonomy","source":"books/vol3/01_introduction/01_introduction.qmd","title":"The H·S·A Exposure Space","status":"ready","treatment":"annotated","question":"Why do tasks with similar turn counts need different controls?","scope":"Positions are illustrative configurations. Closure is the response to exposure, not a fourth coordinate.","regions":{"axes":{"x":0.03,"y":0.07,"w":0.91,"h":0.88,"label":"Horizon, state, authority axes"},"support":{"x":0.3,"y":0.58,"w":0.2,"h":0.1,"label":"Support configuration"},"repair":{"x":0.57,"y":0.46,"w":0.22,"h":0.13,"label":"Repair configuration"},"remediation":{"x":0.42,"y":0.13,"w":0.27,"h":0.16,"label":"Remediation configuration"},"research":{"x":0.61,"y":0.59,"w":0.21,"h":0.15,"label":"Research configuration"}},"steps":[{"title":"Read three exposures","description":"Horizon counts turns, state describes what persists, and authority describes the consequences of granted actions. A long trajectory is not automatically a high-authority task.","focus":["axes"]},{"title":"Confined repair","description":"The repair configuration carries a working copy and workspace authority. Its runtime must isolate those artifacts and enforce the task grant.","focus":["repair"]},{"title":"Durable external effects","description":"The remediation configuration has fewer illustrated turns but durable state and irreversible authority. Its consequences demand stronger controls than turn count alone indicates.","focus":["remediation"]},{"title":"Read-only still carries risk","description":"Support and research are plotted at read-only authority with different horizons and state. Read-only access still requires care about what information can leave the system.","focus":["support","research"]}],"artwork_reviewed":true,"art_sha1":"eb6600dde3ec7497486813f60350c4e031bf093e","art_kind":"svg","art_width":1200,"art_height":828,"art_structural_sha1":"3c6796749df363c24c15db39e0f471bd64e381b6"},"vol3:fig-vol3-human-escrow":{"key":"vol3:fig-vol3-human-escrow","figure_id":"fig-vol3-human-escrow","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"The Approval Gate","status":"ready","treatment":"annotated","question":"What exactly does human approval authorize?","scope":"Approval binds a particular proposal and scope; it is not blanket permission or proof of task acceptance.","regions":{"payload":{"x":0.02,"y":0.07,"w":0.96,"h":0.12,"label":"Exact proposal artifact"},"fields":{"x":0.02,"y":0.19,"w":0.96,"h":0.13,"label":"Approval-bound fields"},"digest":{"x":0.02,"y":0.33,"w":0.96,"h":0.08,"label":"Approval digest"},"held":{"x":0.02,"y":0.56,"w":0.61,"h":0.11,"label":"Hold review and decision"},"recheck":{"x":0.63,"y":0.53,"w":0.16,"h":0.47,"label":"Dispatch recheck boundary"},"outcome":{"x":0.44,"y":0.56,"w":0.54,"h":0.32,"label":"Admitted or refused result"}},"steps":[{"title":"Bind the actual action","description":"The reviewer sees the exact r18 proposal and named check records. Destination, evidence, preconditions, expiry, and requesting trajectory are part of what is approved.","focus":["payload","fields"]},{"title":"Keep approval immutable","description":"The approval digest binds every displayed field. Changing the artifact or arguments changes what must be approved.","focus":["digest"]},{"title":"Wait without executing","description":"The proposal stays in AWAITING_APPROVAL while a reviewer decides. The model is not asked to approve its own action, and denied or expired requests are refused.","focus":["held"]},{"title":"Recheck at dispatch","description":"An approval is usable only while current and while capacity and guards allow admission. An approved request with no capacity stays held; a stale one is refused.","focus":["recheck","outcome"]}],"artwork_reviewed":true,"art_sha1":"0d2f50dc25e0a6d2b0ff1c4d1e94364bc1215ead","art_kind":"svg","art_width":1200,"art_height":822,"art_structural_sha1":"bca0ea356719214ce1498567f1e77f2759d29e88"},"vol3:fig-vol3-index-invalidation":{"key":"vol3:fig-vol3-index-invalidation","figure_id":"fig-vol3-index-invalidation","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"Three Responses to a Source Edit","status":"ready","treatment":"annotated","question":"How can background indexing avoid serving stale content as current?","scope":"The time labels are this figure’s reference estimates; freshness exclusion is a correctness rule, not a universal latency guarantee.","regions":{"sync":{"x":0.02,"y":0.03,"w":0.96,"h":0.27,"label":"Synchronous refresh"},"unsafe":{"x":0.02,"y":0.31,"w":0.96,"h":0.27,"label":"Unchecked background refresh"},"safe":{"x":0.02,"y":0.59,"w":0.96,"h":0.27,"label":"Background refresh with exclusion"},"window":{"x":0.32,"y":0.88,"w":0.42,"h":0.08,"label":"Refresh window"}},"steps":[{"title":"Pay freshness on the write path","description":"Synchronous indexing blocks the write path while r18 is parsed and embedded. Queries then receive the refreshed entries.","focus":["sync"]},{"title":"Find the unsafe window","description":"Without a generation check, background indexing leaves r17 admitted as current after r18 commits. Faster write completion does not make that claim correct.","focus":["unsafe"]},{"title":"Exclude old entries immediately","description":"With exclusion, r17 is not admitted as current during the refresh window. The query uses a direct read or an explicitly partial result instead.","focus":["safe"]},{"title":"Publish only if still current","description":"The rebuilt r18 entries become available only after a current-generation check. A later write would require another freshness decision.","focus":["safe","window"]}],"artwork_reviewed":true,"art_sha1":"eddc11885334d608711118d1cf15f7b33938d560","art_kind":"svg","art_width":1200,"art_height":787,"art_structural_sha1":"c4caebf55d361cc8e5912b1d68a56f123e4010d2"},"vol3:fig-vol3-instruction-data-cohabitation":{"key":"vol3:fig-vol3-instruction-data-cohabitation","figure_id":"fig-vol3-instruction-data-cohabitation","source":"books/vol3/09_security/09_security.qmd","title":"One Sequence, No Enforced Privilege","status":"ready","treatment":"annotated","question":"Where does an enforced release policy sit when instructions and untrusted observations share one input sequence?","scope":"The token connections illustrate shared input, not quantified influence. Role markers and advisory instructions create no enforced privilege boundary inside the model.","regions":{"trusted":{"x":0.045,"y":0.04,"w":0.53,"h":0.235,"label":"Application, tool, and user inputs"},"advisory":{"x":0.575,"y":0.04,"w":0.185,"h":0.235,"label":"Advisory treat-as-data input"},"readme":{"x":0.765,"y":0.04,"w":0.19,"h":0.235,"label":"Attacker-controlled README"},"model":{"x":0.315,"y":0.51,"w":0.315,"h":0.13,"label":"Foundation model"},"proposal":{"x":0.315,"y":0.705,"w":0.315,"h":0.155,"label":"Proposed tool call"},"policy":{"x":0.72,"y":0.56,"w":0.245,"h":0.34,"label":"Runtime release and evidence checks"}},"steps":[{"title":"Recognize the mixed sequence","description":"Application instructions, tool definitions, and the user request enter the same token sequence as the README observation. Different labels identify sources but do not enforce separation inside generation.","focus":["trusted","readme"]},{"title":"Keep advisory instructions in perspective","description":"The instruction to treat the README as data is itself more input. It can guide generation but cannot mechanically prevent an untrusted observation from changing a proposal.","focus":["advisory","model"]},{"title":"Check the proposal outside generation","description":"The model produces a proposed package_search call. The runtime’s release and evidence checks reject the fixture-bearing proposal before dispatch.","focus":["proposal","policy"]}],"artwork_reviewed":true,"art_sha1":"d7e09cfb36c379069ca4b4414cab762ffa02f7bb","art_kind":"svg","art_width":1200,"art_height":634,"art_structural_sha1":"05f5d16912c3113264d6b12e22960c4440f566ce"},"vol3:fig-vol3-invalidation-graph":{"key":"vol3:fig-vol3-invalidation-graph","figure_id":"fig-vol3-invalidation-graph","source":"books/vol3/04_context_engineering/04_context_engineering.qmd","title":"Invalidation Follows Recorded Dependencies","status":"ready","treatment":"annotated","question":"Which evidence becomes historical after editing pool.py?","scope":"Propagation follows recorded dependencies; an old observation remains true of its recorded revision.","regions":{"write":{"x":0.02,"y":0.18,"w":0.25,"h":0.15,"label":"Source revision changes"},"historical":{"x":0.31,"y":0.18,"w":0.34,"h":0.38,"label":"Affected observations"},"hypothesis":{"x":0.73,"y":0.25,"w":0.25,"h":0.21,"label":"Hypothesis to reassess"},"docs":{"x":0.02,"y":0.7,"w":0.63,"h":0.15,"label":"Unchanged documentation path"},"note":{"x":0.73,"y":0.7,"w":0.25,"h":0.15,"label":"Unchanged API note"}},"steps":[{"title":"Identify the changed source","description":"The write advances src/pool.py from r17 to r18. Its red outgoing dependencies identify which observations used that source.","focus":["write"]},{"title":"Keep old observations as history","description":"The source excerpt and controlled test run refer to r17. They remain historical evidence, but no longer establish the corresponding current-state claim.","focus":["historical"]},{"title":"Reassess dependent conclusions","description":"Both affected observations supported the missed-notification hypothesis. The derived conclusion therefore needs reassessment rather than blind retention.","focus":["hypothesis"]},{"title":"Avoid unrelated invalidation","description":"The documentation excerpt and its API usage note are outside the changed dependency path. They keep their status in this recorded graph.","focus":["docs","note"]}],"artwork_reviewed":true,"art_sha1":"1e92a90ae5fbd38a3ec0f1d8b2b2e1dce692592b","art_kind":"svg","art_width":1200,"art_height":647,"art_structural_sha1":"9cbc6ee3cd7b51404d2562373df1120f750f6674"},"vol3:fig-vol3-isolation-spectrum":{"key":"vol3:fig-vol3-isolation-spectrum","figure_id":"fig-vol3-isolation-spectrum","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"Where a System Call Lands","status":"ready","treatment":"annotated","question":"Where is a workload call mediated under each isolation design?","scope":"This comparison locates boundaries, not a universal security ranking or a performance benchmark.","regions":{"container":{"x":0.02,"y":0.02,"w":0.24,"h":0.85,"label":"Shared-kernel container"},"userspace":{"x":0.27,"y":0.02,"w":0.24,"h":0.85,"label":"User-space kernel"},"microvm":{"x":0.52,"y":0.02,"w":0.24,"h":0.85,"label":"MicroVM"},"bytecode":{"x":0.77,"y":0.02,"w":0.22,"h":0.85,"label":"Restricted bytecode"},"host":{"x":0.02,"y":0.88,"w":0.97,"h":0.1,"label":"Host kernel"}},"steps":[{"title":"A container still reaches the host","description":"The shared-kernel container sends calls through a filter to the host kernel. The filter reduces the exposed interface but does not insert a guest kernel.","focus":["container","host"]},{"title":"Emulate calls in user space","description":"The user-space kernel traps workload calls and emulates them, issuing a reduced set of host calls itself.","focus":["userspace"]},{"title":"Separate a guest kernel","description":"The microVM runs native calls against its guest kernel. Device I/O crosses the monitor boundary before host interaction.","focus":["microvm"]},{"title":"Expose only imported functions","description":"Restricted bytecode accesses host functions through runtime imports and linear memory. The permitted imports define the interface that the host must secure.","focus":["bytecode"]}],"artwork_reviewed":true,"art_sha1":"8c70fa95ee2d8d93ff85773577033aa6185f0981","art_kind":"svg","art_width":1200,"art_height":638,"art_structural_sha1":"6fca5c39b5d4c70ec3d881ee31849535eb97c64b"},"vol3:fig-vol3-ivf-pq":{"key":"vol3:fig-vol3-ivf-pq","figure_id":"fig-vol3-ivf-pq","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"IVF-PQ Build and Query","status":"ready","treatment":"annotated","question":"How does IVF-PQ score compressed vectors?","scope":"Printed dimensions and compression describe this illustrated configuration; code distances approximate full-vector distances.","regions":{"encode":{"x":0.02,"y":0.03,"w":0.96,"h":0.34,"label":"Subvectors codebooks and codes"},"lists":{"x":0.26,"y":0.46,"w":0.7,"h":0.18,"label":"Coarse inverted lists"},"query":{"x":0.04,"y":0.79,"w":0.35,"h":0.14,"label":"Query chooses cells"},"lut":{"x":0.43,"y":0.74,"w":0.26,"h":0.22,"label":"Distance lookup table"},"score":{"x":0.71,"y":0.79,"w":0.25,"h":0.15,"label":"Score stored codes"}},"steps":[{"title":"Encode a stored vector","description":"The FP16 vector is split into subvectors. Each subvector selects a codebook centroid, leaving one code index per subvector instead of the original values.","focus":["encode"]},{"title":"Partition codes into coarse cells","description":"Each encoded vector is appended to an inverted list. At query time only the nprobe nearest coarse cells are chosen for scanning.","focus":["lists","query"]},{"title":"Precompute query distances","description":"The query builds a lookup table of distances to subvector centroids. The table is shared across the candidate codes being scored.","focus":["lut"]},{"title":"Sum code lookups","description":"Each candidate score sums the entries named by its stored indices. This cuts stored-vector traffic while introducing quantization and cell-selection approximation.","focus":["score","encode"]}],"artwork_reviewed":true,"art_sha1":"08ae2e3fb5c7f895323cf0a1911db9e09e9831c8","art_kind":"svg","art_width":1200,"art_height":934,"art_structural_sha1":"8214a4b9de68142c3d0c39f88544ffb8a48e1e7e"},"vol3:fig-vol3-kv-footprint-by-architecture":{"key":"vol3:fig-vol3-kv-footprint-by-architecture","figure_id":"fig-vol3-kv-footprint-by-architecture","source":"books/vol3/05_kv_cache/05_kv_cache.qmd","title":"Attention Architecture Sets the KV Payload","status":"ready","treatment":"annotated","question":"Why can a larger model retain less KV state per token?","scope":"The figure compares declared model geometries at 16-bit precision. Accelerator reference lines show total memory, not memory wholly available to KV state.","regions":{"bars":{"x":0.02,"y":0.04,"w":0.46,"h":0.9,"label":"Per-token KV payload by architecture"},"capacity":{"x":0.52,"y":0.04,"w":0.46,"h":0.33,"label":"Single-accelerator memory reference lines"},"curves":{"x":0.52,"y":0.32,"w":0.46,"h":0.6,"label":"One-session KV growth curves"},"extrapolated":{"x":0.58,"y":0.07,"w":0.4,"h":0.49,"label":"Dotted multi-head extrapolation"}},"steps":[{"title":"Compare stored attention state","description":"The left panel groups the published geometries by MHA, GQA, and MLA. Parameter count alone does not determine the amount of retained key and value state.","focus":["bars"]},{"title":"Accumulate state over retained tokens","description":"Each line in the right panel grows with retained context length for one representative architecture. A lower per-token payload permits a longer context at the same KV capacity.","focus":["curves"]},{"title":"Respect the comparison limits","description":"Horizontal lines are whole-accelerator memory references; weights and other runtime allocations also consume that memory. The dotted MHA segment extends beyond that model’s trained window for scale only.","focus":["capacity","extrapolated"]}],"artwork_reviewed":true,"art_sha1":"e00f8a90754cb605b7df4ce8df41d5f49ed22c13","art_kind":"png","art_width":5939,"art_height":2460},"vol3:fig-vol3-leaderboard-rank-ties":{"key":"vol3:fig-vol3-leaderboard-rank-ties","figure_id":"fig-vol3-leaderboard-rank-ties","source":"books/vol3/13_evaluation/13_evaluation.qmd","title":"Neighboring Ranks Are Statistical Ties","status":"ready","treatment":"annotated","question":"How much evidence separates neighboring leaderboard ranks?","scope":"The figure uses reported standard errors for one evaluator and scaffold. Visual interval overlap alone is not the independent-samples significance test used in the chapter.","regions":{"top":{"x":0.02,"y":0.04,"w":0.96,"h":0.24,"label":"Leading score estimates and intervals"},"middle":{"x":0.02,"y":0.29,"w":0.96,"h":0.35,"label":"Neighboring middle ranks"},"lower":{"x":0.02,"y":0.65,"w":0.96,"h":0.29,"label":"Lower shown ranks"},"axis":{"x":0.23,"y":0.93,"w":0.75,"h":0.06,"label":"Tasks resolved percentage axis"}},"steps":[{"title":"A point estimate has uncertainty","description":"The dot gives tasks resolved and the horizontal bar its 95 percent interval. The top score does not make all nearby configurations distinguishable.","focus":["top","axis"]},{"title":"Inspect neighboring ranks","description":"Neighboring rows have small point differences beside much wider uncertainty intervals. The chapter’s independent-samples comparison, rather than dot ordering alone, assesses whether such differences are resolved.","focus":["middle"]},{"title":"Separate large and small gaps","description":"Ranks several places apart can have stronger separation than adjacent entries. These conclusions remain conditional on this evaluator, scaffold, task sample, and reported uncertainty.","focus":["top","lower"]}],"artwork_reviewed":true,"art_sha1":"dc6e3fe61802df382d35ecc89fe57e4eca6dcc54","art_kind":"png","art_width":4984,"art_height":3158},"vol3:fig-vol3-lexical-vs-ast":{"key":"vol3:fig-vol3-lexical-vs-ast","figure_id":"fig-vol3-lexical-vs-ast","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"Occurrences vs. Relationships","status":"ready","treatment":"annotated","question":"What can a structural edge tell us that a word match cannot?","scope":"Static call edges indicate possible relationships, not observed execution; unresolved dynamic calls remain unknown.","regions":{"lexical":{"x":0.02,"y":0.03,"w":0.96,"h":0.37,"label":"Lexical postings"},"chain":{"x":0.05,"y":0.52,"w":0.9,"h":0.37,"label":"Resolved caller chain"},"unknown":{"x":0.1,"y":0.79,"w":0.3,"h":0.1,"label":"Unresolved dynamic target"}},"steps":[{"title":"Find literal occurrences","description":"The notify postings include both src/pool.py and the failure log. A term occurrence does not establish a caller-callee relationship.","focus":["lexical"]},{"title":"Follow the resolved structure","description":"The test function calls the pool return method, which calls _available.notify(). Those directed edges answer a structural question beyond matching text.","focus":["chain"]},{"title":"Preserve unresolved coverage","description":"The dashed CALLS ? branch ends at target unknown. Missing static resolution does not prove the runtime path cannot occur.","focus":["unknown"]}],"artwork_reviewed":true,"art_sha1":"a744b65951f3eac73abc78ae058653b5d5c8631f","art_kind":"svg","art_width":1200,"art_height":750,"art_structural_sha1":"27936135e5066fc7018927b1ba8fe51e5578479a"},"vol3:fig-vol3-loss-masking":{"key":"vol3:fig-vol3-loss-masking","figure_id":"fig-vol3-loss-masking","source":"books/vol3/16_fine_tuning/16_fine_tuning.qmd","title":"Observation Loss Masking","status":"ready","treatment":"annotated","question":"Does a zero loss mask mean the model ignores that segment?","scope":"This simplified serialization omits a selected schema request and its returned schema; only the seven printed segments are inspected.","regions":{"supplied":{"x":0.17,"y":0.04,"w":0.23,"h":0.15,"label":"Supplied prompt and task"},"refused":{"x":0.41,"y":0.24,"w":0.12,"h":0.15,"label":"Refused proposal"},"environment":{"x":0.52,"y":0.45,"w":0.34,"h":0.15,"label":"Environment observations"},"targets":{"x":0.59,"y":0.24,"w":0.38,"h":0.15,"label":"Corrected call and final answer"},"mask":{"x":0.17,"y":0.69,"w":0.8,"h":0.1,"label":"Direct loss mask"},"attention":{"x":0.17,"y":0.85,"w":0.8,"h":0.12,"label":"Context influence through attention"}},"steps":[{"title":"Keep authorship distinct","description":"The supplied, policy, and environment lanes identify where each serialized segment originated. A tool result is an observation, not a policy action to imitate.","focus":["supplied","environment"]},{"title":"Select corrected policy responses","description":"The corrected tool call and final response carry mask one. The refused proposal and environment messages carry zero direct imitation loss.","focus":["targets","refused","mask"]},{"title":"Retain conditioning context","description":"The green attention path reaches earlier segments, including those with zero direct loss. Later selected targets can still update the parameters that encode that context.","focus":["attention"]},{"title":"Avoid training an environment impersonator","description":"Leaving observations out of direct policy loss preserves the conditional action objective. It does not remove observations from the model input.","focus":["environment","mask"]}],"artwork_reviewed":true,"art_sha1":"0547185a3884f4b4a8a534094692bf79d2e51f68","art_kind":"svg","art_width":1200,"art_height":560,"art_structural_sha1":"8b281f83ceedc4de43ce198dcc4f91d56f8516c3"},"vol3:fig-vol3-measured-task-horizon":{"key":"vol3:fig-vol3-measured-task-horizon","figure_id":"fig-vol3-measured-task-horizon","source":"books/vol3/01_introduction/01_introduction.qmd","title":"Measured Task Horizon","status":"ready","treatment":"annotated","question":"What does a measured 50 percent task horizon say about agent reliability?","scope":"These are recorded benchmark estimates with confidence intervals. Expert task duration is not an agent’s runtime, and the fitted historical trend is not a forecast.","regions":{"early":{"x":0.03,"y":0.52,"w":0.46,"h":0.4,"label":"Earlier measured model horizons"},"recent":{"x":0.46,"y":0.08,"w":0.5,"h":0.57,"label":"Recent frontier and other models"},"fit":{"x":0.42,"y":0.17,"w":0.54,"h":0.52,"label":"Since-2023 log-linear fit"},"legend":{"x":0.14,"y":0.04,"w":0.48,"h":0.13,"label":"Markers and fit legend"}},"steps":[{"title":"Read the measured quantity","description":"The vertical axis gives expert-time task length at which the agent succeeds in half its attempts. It is logarithmic: equal vertical spacing represents multiplicative changes in task length.","focus":["early"]},{"title":"Distinguish frontier from other evaluations","description":"Filled points were frontier models at release; open points were not. Vertical bars retain uncertainty around the measured horizons.","focus":["recent","legend"]},{"title":"Interpret the fitted line cautiously","description":"The dashed straight fit on the logarithmic axis represents an exponential historical trend since 2023. It does not show a guarantee of future gains or reliable completion of every task below the horizon.","focus":["fit"]}],"artwork_reviewed":true,"art_sha1":"61016e68225e1ede035496fd2003f4aacb8d7cfe","art_kind":"png","art_width":4414,"art_height":2604},"vol3:fig-vol3-model-call-surface":{"key":"vol3:fig-vol3-model-call-surface","figure_id":"fig-vol3-model-call-surface","source":"books/vol3/02_foundation_model/02_foundation_model.qmd","title":"The Model Call Surface","status":"ready","treatment":"annotated","question":"Who decides what happens after a model response?","scope":"The model proposes; the runtime owns execution, verification, and quarantine.","regions":{"request":{"x":0.02,"y":0.03,"w":0.33,"h":0.45,"label":"Request and messages"},"model":{"x":0.39,"y":0.12,"w":0.22,"h":0.27,"label":"Frozen model"},"response":{"x":0.66,"y":0.03,"w":0.32,"h":0.45,"label":"Response envelope"},"route":{"x":0.39,"y":0.65,"w":0.55,"h":0.11,"label":"Route and authorize"},"sandbox":{"x":0.09,"y":0.65,"w":0.22,"h":0.11,"label":"Sandbox and result return"},"terminal":{"x":0.39,"y":0.81,"w":0.57,"h":0.11,"label":"Verification and quarantine"}},"steps":[{"title":"Supply the next call","description":"Messages, tool definitions, and limits enter the frozen model. A tool result becomes visible only when the runtime includes it in a later request.","focus":["request","model"]},{"title":"Inspect the envelope","description":"The response is a proposal with usage counts and a stop reason. A plausible payload alone does not authorize any action.","focus":["response"]},{"title":"Admit a tool action","description":"The tool-call branch passes through validation and authorization before sandbox execution. Its empirical result returns as a tool message.","focus":["route","sandbox"]},{"title":"Separate ending paths","description":"An end-of-turn answer goes to verification; output stopped at its limit goes to quarantine. Neither path is permission to execute a partial proposal.","focus":["terminal"]}],"artwork_reviewed":true,"art_sha1":"ec8d47783175694001683c71b06a397a44ee130b","art_kind":"svg","art_width":1200,"art_height":736,"art_structural_sha1":"57b811693e57bcf2e23ed8a266ef7a219236a5b3"},"vol3:fig-vol3-model-calls-resolved-vs-failed":{"key":"vol3:fig-vol3-model-calls-resolved-vs-failed","figure_id":"fig-vol3-model-calls-resolved-vs-failed","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"Failed Runs Take More Calls","status":"ready","treatment":"annotated","question":"What can successful-run call counts tell us about a candidate ceiling?","scope":"These are post-hoc distributions of unconstrained runs. Enforcing a visible ceiling can change agent behavior, so a candidate policy still needs a new evaluation.","regions":{"first":{"x":0.05,"y":0.03,"w":0.18,"h":0.83,"label":"SWE-agent 0.x distribution"},"same1":{"x":0.24,"y":0.03,"w":0.18,"h":0.83,"label":"SWE-agent 1.1 distribution"},"same2":{"x":0.43,"y":0.03,"w":0.18,"h":0.83,"label":"OpenHands distribution"},"mini":{"x":0.62,"y":0.03,"w":0.18,"h":0.83,"label":"mini-SWE-agent Opus distribution"},"codex":{"x":0.81,"y":0.03,"w":0.18,"h":0.83,"label":"mini-SWE-agent Codex distribution"},"legend":{"x":0.41,"y":0.9,"w":0.2,"h":0.07,"label":"Accepted solid and failed dashed"}},"steps":[{"title":"Read cumulative call distributions","description":"In the first panel the accepted solid curve rises before the failed dashed curve. At a given call count, more eventual successes have already finished.","focus":["first","legend"]},{"title":"Inspect what the ceiling removes","description":"The first panel’s vertical ceiling would halt 31% of eventual failures and 9% of eventual accepted runs. This is a retrospective trade-off, not proof of those outcomes under a changed policy.","focus":["first"]},{"title":"Avoid transferring a threshold blindly","description":"SWE-agent 1.1 and OpenHands use the same named model but have different call distributions and ceiling locations. The harness configuration affects the candidate limit.","focus":["same1","same2"]},{"title":"Evaluate a policy-specific ceiling","description":"The remaining configurations show the same need to separate failed and accepted tails. Choose a candidate from the appropriate configuration, then measure with that ceiling actually enforced.","focus":["mini","codex"]}],"artwork_reviewed":true,"art_sha1":"dbcfe86205c92181699f0e633dc5054aa4885fa3","art_kind":"png","art_width":5939,"art_height":1939},"vol3:fig-vol3-model-cascade-flowchart":{"key":"vol3:fig-vol3-model-cascade-flowchart","figure_id":"fig-vol3-model-cascade-flowchart","source":"books/vol3/19_agent_economics/19_agent_economics.qmd","title":"A Gated Three-Tier Cascade","status":"ready","treatment":"annotated","question":"How does a cascade lower cost per accepted result while charging unsuccessful attempts?","scope":"Prices and acceptance rates are stipulated workload inputs. The direct-frontier cohort is a separate baseline, and accepted gate verdicts are not proof of every operational property.","regions":{"first":{"x":0.02,"y":0.04,"w":0.96,"h":0.2,"label":"First-tier cohort and gate"},"second":{"x":0.02,"y":0.25,"w":0.96,"h":0.2,"label":"Rejected remainder reaches tier two"},"third":{"x":0.02,"y":0.46,"w":0.96,"h":0.2,"label":"Final tier and gate"},"unresolved":{"x":0.28,"y":0.6,"w":0.2,"h":0.075,"label":"Final unresolved tasks"},"accepted":{"x":0.76,"y":0.63,"w":0.22,"h":0.08,"label":"Total accepted outcomes"},"cost":{"x":0.02,"y":0.79,"w":0.96,"h":0.2,"label":"Cost per accepted result comparison"}},"steps":[{"title":"Charge the initial cohort’s gate","description":"All initiated tasks reach tier one and its assessment. The passing portion exits to accepted outcomes; only the rejected remainder moves downward.","focus":["first"]},{"title":"Pay for every reached attempt","description":"Tier two and tier three each charge their call and gate to the tasks that reach them. Earlier failed attempts stay in total cohort cost when a later tier succeeds.","focus":["second","third"]},{"title":"Keep unresolved tasks visible","description":"The final gate still charges its assessment. Its rejected sliver remains unresolved rather than being folded into accepted outcomes.","focus":["third","unresolved","accepted"]},{"title":"Divide by accepted results, not initiated tasks","description":"The lower bars charge all attempts to the accepted outcomes. Compare this with the separately stipulated direct-frontier cohort, rather than applying the last tier’s conditional acceptance to every initial task.","focus":["cost","accepted"]}],"artwork_reviewed":true,"art_sha1":"e1310192cd26240a4bc03d28397b3ed29e6cca98","art_kind":"svg","art_width":1200,"art_height":795,"art_structural_sha1":"5d902ee94b073f0bc15e92f77cf9f21d55546088"},"vol3:fig-vol3-multi-agent-topologies":{"key":"vol3:fig-vol3-multi-agent-topologies","figure_id":"fig-vol3-multi-agent-topologies","source":"books/vol3/18_multi_agent/18_multi_agent.qmd","title":"Four Coordination Arrangements","status":"ready","treatment":"annotated","question":"Which boundary carries coordination in each arrangement?","scope":"Delivery counts describe the declared round patterns; they are not token cost, latency, or mandatory traffic on every actor link.","regions":{"supervisor":{"x":0.02,"y":0.02,"w":0.47,"h":0.46,"label":"Supervisor and workers"},"pipeline":{"x":0.51,"y":0.02,"w":0.47,"h":0.46,"label":"Pipeline and bounded queues"},"board":{"x":0.02,"y":0.51,"w":0.47,"h":0.47,"label":"Shared blackboard"},"actors":{"x":0.51,"y":0.51,"w":0.47,"h":0.47,"label":"Actors and mailboxes"}},"steps":[{"title":"Envelopes and receipts","description":"The supervisor sends one envelope down and receives one receipt back per worker. That declared round has 2N deliveries and requires result checking at the supervisor boundary.","focus":["supervisor"]},{"title":"Bound the queue","description":"Pipeline artifacts pass through explicit queue slots between stages. Capacity and downstream progress determine whether an upstream stage can continue.","focus":["pipeline"]},{"title":"Coordinate shared publication","description":"Workers claim tasks and publish versioned artifacts through a shared store. Concurrent claims and publications need explicit state consistency rules.","focus":["board"]},{"title":"Address messages to mailboxes","description":"Actors exchange addressed messages through their mailboxes. The faint full mesh shows possible connections, while solid arrows show only selected messages.","focus":["actors"]}],"artwork_reviewed":true,"art_sha1":"fecefb6477cdfc53b62d51d41fa7addb9f9b0da4","art_kind":"svg","art_width":1200,"art_height":795,"art_structural_sha1":"f89b5f22694c40fc43183f5e6845aeb40026bbaf"},"vol3:fig-vol3-network-egress":{"key":"vol3:fig-vol3-network-egress","figure_id":"fig-vol3-network-egress","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"Two Enforcement Points Outside the Guest","status":"ready","treatment":"annotated","question":"Why does packet filtering need an operation-aware mediator?","scope":"The guest has no default route in this design. The pictured approved fetch is a narrow capability, not general repository access.","regions":{"guest":{"x":0.02,"y":0.08,"w":0.24,"h":0.85,"label":"Guest requests"},"filter":{"x":0.34,"y":0.08,"w":0.1,"h":0.85,"label":"Packet filter"},"mediator":{"x":0.57,"y":0.08,"w":0.15,"h":0.85,"label":"Operation-aware mediator"},"destinations":{"x":0.76,"y":0.08,"w":0.23,"h":0.85,"label":"External destinations"}},"steps":[{"title":"Route to a constrained mediator","description":"Fetch approved repo reaches the mediator through the packet filter. The mediator admits the operation and adds the credential outside the guest.","focus":["guest","filter","mediator"]},{"title":"Same route, different operation","description":"Push or another repo reaches the mediator but is denied there. Address and port controls alone cannot express this operation distinction.","focus":["mediator"]},{"title":"Block bypass routes","description":"The direct socket is dropped and the name lookup has no resolver route. The metadata host and external DNS server remain unreached.","focus":["filter","destinations"]}],"artwork_reviewed":true,"art_sha1":"138d59062a57d2bf3f2323b6da382576b542fa67","art_kind":"svg","art_width":1200,"art_height":556,"art_structural_sha1":"7db9ed99b9033b163b57b1ca8a87cb42b7829a4e"},"vol3:fig-vol3-occ-worktrees":{"key":"vol3:fig-vol3-occ-worktrees","figure_id":"fig-vol3-occ-worktrees","source":"books/vol3/18_multi_agent/18_multi_agent.qmd","title":"Private Workspaces and Guarded Publication","status":"ready","treatment":"annotated","question":"Why is a textually clean merge insufficient for publishing concurrent work?","scope":"Worktrees isolate Git working state, not security authority. Publication must validate exact dependencies and the captured integration head.","regions":{"worktrees":{"x":0.02,"y":0.02,"w":0.47,"h":0.43,"label":"Private worktrees and sandboxes"},"graph":{"x":0.51,"y":0.02,"w":0.47,"h":0.43,"label":"Clean merge with stale dependency"},"validate":{"x":0.02,"y":0.67,"w":0.59,"h":0.17,"label":"Revalidate, build, check"},"publish":{"x":0.63,"y":0.67,"w":0.34,"h":0.17,"label":"Atomic guarded publication"},"loop":{"x":0.09,"y":0.57,"w":0.61,"h":0.1,"label":"Head-moved return path"}},"steps":[{"title":"Separate working state and authority","description":"Each worktree has files, index, and HEAD while repository storage is shared. The dashed sandbox, not the worktree, scopes worker writes.","focus":["worktrees"]},{"title":"A clean merge can be semantically stale","description":"The caller edits separate files but relies on the base interface. Merging at the changed head preserves that stale dependency unless it is revalidated.","focus":["graph"]},{"title":"Test the exact integration candidate","description":"Revalidation precedes building and checking h_candidate. Evidence for an earlier worker tree is not automatically evidence for this combined candidate.","focus":["validate"]},{"title":"Publish against the captured head","description":"Atomic update expects h_head and the publication guard. If the head moved, the attempt returns to validation rather than overwriting intervening work.","focus":["publish","loop"]}],"artwork_reviewed":true,"art_sha1":"67cdbd932b7c3af46cbc5d1ca8df44f07623970f","art_kind":"svg","art_width":1200,"art_height":714,"art_structural_sha1":"939606c6b90ffb109b9c6ab63a0526bb3d887c7b"},"vol3:fig-vol3-offensive-capability-trend":{"key":"vol3:fig-vol3-offensive-capability-trend","figure_id":"fig-vol3-offensive-capability-trend","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"The Code Inside the Boundary Is Getting Better at Exploits","status":"ready","treatment":"annotated","question":"What does the exploit benchmark trend imply for sandbox design?","scope":"The plotted solve rates are benchmark observations under differing agent configurations. Lab-reported points and leaderboard points are distinct evidence sources, not a controlled causal comparison.","regions":{"earlier":{"x":0.08,"y":0.61,"w":0.53,"h":0.3,"label":"Earlier leaderboard observations"},"later":{"x":0.61,"y":0.08,"w":0.35,"h":0.59,"label":"Later leaderboard and lab-reported points"},"legend":{"x":0.12,"y":0.03,"w":0.53,"h":0.16,"label":"Evidence-source legend"},"best":{"x":0.1,"y":0.14,"w":0.84,"h":0.75,"label":"Running-best step trace"}},"steps":[{"title":"Read the evidence source","description":"Filled points come from the benchmark leaderboard; open points come from model or system cards. The most recent reported gains must be read with that provenance visible.","focus":["legend","later"]},{"title":"Compare capability across releases","description":"Earlier observations cluster lower while later reported configurations solve more tasks without hints. Release date and configuration are observed together, so this is not an isolated intervention on model quality.","focus":["earlier","later"]},{"title":"Contain capable admitted code","description":"The dashed step follows the best recorded result to date rather than interpolating every model’s capability. A sandbox must enforce boundaries even when the code it admits is increasingly effective at exploitation.","focus":["best"]}],"artwork_reviewed":true,"art_sha1":"81047c2cb578ff242ac761dab11de32f53a428f2","art_kind":"png","art_width":4161,"art_height":2452},"vol3:fig-vol3-open-vs-closed-loop-control":{"key":"vol3:fig-vol3-open-vs-closed-loop-control","figure_id":"fig-vol3-open-vs-closed-loop-control","source":"books/vol3/01_introduction/01_introduction.qmd","title":"A Person or a Runtime Closes the Loop","status":"ready","treatment":"annotated","question":"Who can turn a model proposal into an environmental action?","scope":"The two panels compare who closes the same repair loop; neither grants authority to the model.","regions":{"person":{"x":0.03,"y":0.03,"w":0.45,"h":0.91,"label":"Person closes the loop"},"model":{"x":0.65,"y":0.12,"w":0.24,"h":0.16,"label":"Model holds no authority"},"runtime":{"x":0.65,"y":0.45,"w":0.24,"h":0.17,"label":"Runtime grants actions"},"evidence":{"x":0.55,"y":0.66,"w":0.44,"h":0.29,"label":"Sandbox and verifier evidence"}},"steps":[{"title":"Manual feedback","description":"In panel A, the developer runs commands and carries the terminal error back to the model. The answer alone does not execute a tool.","focus":["person"]},{"title":"Proposal crosses a boundary","description":"In panel B, the foundation model returns a proposal to the agent runtime. The dashed line separates proposing from acting.","focus":["model","runtime"]},{"title":"Dispatch and evidence","description":"The runtime grants each action before dispatching it to the sandbox. Tests and linters return evidence to the runtime, which can use it in the next turn.","focus":["runtime","evidence"]}],"artwork_reviewed":true,"art_sha1":"dd859df45fe31b16dbc4157554ced4b8287bbfd9","art_kind":"svg","art_width":1200,"art_height":617,"art_structural_sha1":"d1808f573788a1d15e824b65389d5cda238d8784"},"vol3:fig-vol3-plan-revision":{"key":"vol3:fig-vol3-plan-revision","figure_id":"fig-vol3-plan-revision","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Invalidation and Scoped Regeneration","status":"ready","treatment":"annotated","question":"Which candidate artifacts need regeneration after a test contradicts the diagnosis?","scope":"These nodes are candidate artifacts, not executed effects. Safe retention requires complete recorded dependency edges and checks of each replacement.","regions":{"newtest":{"x":0.04,"y":0.31,"w":0.2,"h":0.08,"label":"Waiter-return test contradicts diagnosis"},"invalid":{"x":0.285,"y":0.12,"w":0.68,"h":0.19,"label":"Unsupported diagnosis and descendants"},"kept":{"x":0.04,"y":0.385,"w":0.45,"h":0.09,"label":"API declaration and retained notes"},"frontier":{"x":0.04,"y":0.61,"w":0.2,"h":0.26,"label":"Supported inputs and new observation"},"regenerated":{"x":0.28,"y":0.63,"w":0.69,"h":0.17,"label":"Regenerated candidate branch"},"retained":{"x":0.04,"y":0.87,"w":0.45,"h":0.09,"label":"Separately retained API notes"}},"steps":[{"title":"Invalidate the contradicted branch","description":"The waiter-return test removes support for the timeout diagnosis. The patch candidate and check selection depend on that diagnosis, so both need review.","focus":["newtest","invalid"]},{"title":"Retain independently supported work","description":"The API notes still follow from the unchanged API declaration. Their separate support permits retention while the contradicted branch is reconsidered.","focus":["kept"]},{"title":"Regenerate from the supported frontier","description":"The next request uses the retained source and failure observation together with the new test. It regenerates a missed-notification diagnosis, a notify-on-return patch, and an ordering check.","focus":["frontier","regenerated"]},{"title":"Check the replacement without erasing effects","description":"The retained API notes remain outside the regenerated branch. Candidate regeneration does not undo a file edit or release a resource; external effects require their own recovery protocol.","focus":["retained","regenerated"]}],"artwork_reviewed":true,"art_sha1":"4be6ad1b1688cdd4f89f386dc2903d32508411e2","art_kind":"svg","art_width":1200,"art_height":828,"art_structural_sha1":"8a08d0ea5dc3b4c1f0a0c46b2fbc494cf6bcd347"},"vol3:fig-vol3-price-at-fixed-capability":{"key":"vol3:fig-vol3-price-at-fixed-capability","figure_id":"fig-vol3-price-at-fixed-capability","source":"books/vol3/19_agent_economics/19_agent_economics.qmd","title":"The Price of a Fixed Capability Falls Fast","status":"ready","treatment":"annotated","question":"What changes when the cheapest price for a fixed benchmark capability falls?","scope":"These historical series end in early 2025 and use the source’s 3:1 input-output price blend. They are neither live prices nor total agent cost per accepted task.","regions":{"early":{"x":0.14,"y":0.06,"w":0.22,"h":0.21,"label":"GPT-3 initial level and first lower price"},"later":{"x":0.58,"y":0.23,"w":0.33,"h":0.57,"label":"Later lower-price steps"},"endpoints":{"x":0.73,"y":0.65,"w":0.22,"h":0.18,"label":"Named latest recorded endpoints"},"legend":{"x":0.13,"y":0.72,"w":0.5,"h":0.15,"label":"Fixed capability thresholds and fitted declines"},"priceaxis":{"x":0.01,"y":0.02,"w":0.11,"h":0.85,"label":"Logarithmic token-price axis"},"dates":{"x":0.12,"y":0.87,"w":0.79,"h":0.11,"label":"Release-date range"}},"steps":[{"title":"Hold the capability threshold fixed","description":"Each legend entry specifies a benchmark capability level. A downward step records a new cheapest model meeting that same level, rather than a weakened benchmark target.","focus":["legend","early"]},{"title":"Read multiplicative price changes correctly","description":"The vertical price axis is logarithmic. Equal vertical distances represent equal price ratios, and the fitted annual declines summarize the source’s historical interval.","focus":["priceaxis","later"]},{"title":"Keep the historical endpoint visible","description":"Model labels identify the first and final recorded offerings on the curves. The series stop in early 2025; the display makes no claim about today’s cheapest offering.","focus":["endpoints","dates"]},{"title":"Separate inference price from episode economics","description":"Falling token price shrinks inference charges. It does not directly shrink verification, sandbox lifetime, cleanup, or human-review costs, and it does not establish acceptance probability.","focus":["legend","endpoints"]}],"artwork_reviewed":true,"art_sha1":"cda854daa0813ade310d0cc4b363eb4fd1969b44","art_kind":"png","art_width":4605,"art_height":2511},"vol3:fig-vol3-provenance-envelope":{"key":"vol3:fig-vol3-provenance-envelope","figure_id":"fig-vol3-provenance-envelope","source":"books/vol3/15_trajectory_curation/15_trajectory_curation.qmd","title":"A Derived Record and Its Lineage","status":"ready","treatment":"annotated","question":"What must a redacted trajectory preserve before it can be admitted for learning?","scope":"Lineage does not authorize reading restricted raw data, and retaining a hash is not retaining the source. A transformed view must be revalidated for its declared use.","regions":{"source":{"x":0.02,"y":0.05,"w":0.285,"h":0.89,"label":"Unmodified source record"},"redact":{"x":0.33,"y":0.43,"w":0.145,"h":0.18,"label":"Versioned redaction policy"},"derived":{"x":0.475,"y":0.05,"w":0.285,"h":0.66,"label":"New derived record"},"parent":{"x":0.28,"y":0.22,"w":0.46,"h":0.1,"label":"Parent reference"},"pending":{"x":0.49,"y":0.565,"w":0.26,"h":0.11,"label":"Assessment pending"},"revalidate":{"x":0.77,"y":0.52,"w":0.21,"h":0.42,"label":"Revalidation and admission"},"reverse":{"x":0.03,"y":0.8,"w":0.6,"h":0.12,"label":"Reverse correction and withdrawal reference"}},"steps":[{"title":"Create a new version","description":"Redaction produces a distinct derived record instead of editing trace_r19_01 in place. The versioned transformation records the changed fields and omissions.","focus":["source","redact","derived"]},{"title":"Retain lineage and partition boundaries","description":"The derived record links to its parent and keeps the same split group. Those references preserve provenance and evaluation separation without granting raw-source access.","focus":["parent","derived"]},{"title":"Revalidate the transformed evidence","description":"The derived assessment is pending. Removing fields can remove the evidence for a target, so revalidation decides which declared use remains supported or must be withheld.","focus":["pending","revalidate"]},{"title":"Propagate later corrections","description":"The source’s reverse reference reaches the derived version for correction or withdrawal. Provenance must work in both directions after transformation.","focus":["reverse"]}],"artwork_reviewed":true,"art_sha1":"95f29c02b6b569b0e63e2fc251e8431016eaac45","art_kind":"svg","art_width":1200,"art_height":519,"art_structural_sha1":"d030ec9bb3859d0a3a3f0a7a2cd20af386f091a4"},"vol3:fig-vol3-quarantined-reader":{"key":"vol3:fig-vol3-quarantined-reader","figure_id":"fig-vol3-quarantined-reader","source":"books/vol3/09_security/09_security.qmd","title":"A Quarantined Reader Between Source and Planner","status":"ready","treatment":"annotated","question":"What does a quarantined reader remove, and why does its output still need policy checks?","scope":"A completed, schema-valid claim remains a claim. Runtime metadata comes from the ingestion record, and typed handles do not bypass checks on resolved content.","regions":{"quarantine":{"x":0.02,"y":0.05,"w":0.35,"h":0.33,"label":"No-tools, no-credentials reader"},"adapter":{"x":0.395,"y":0.13,"w":0.125,"h":0.135,"label":"Schema-checking adapter"},"failure":{"x":0.37,"y":0.425,"w":0.175,"h":0.11,"label":"Incomplete or invalid result"},"record":{"x":0.545,"y":0.05,"w":0.285,"h":0.54,"label":"Claim plus host metadata"},"planner":{"x":0.845,"y":0.13,"w":0.125,"h":0.135,"label":"Planner sees claim"},"monitor":{"x":0.755,"y":0.66,"w":0.22,"h":0.17,"label":"Reference monitor resolves handle"},"store":{"x":0.37,"y":0.72,"w":0.175,"h":0.11,"label":"Handle store"},"tools":{"x":0.755,"y":0.855,"w":0.22,"h":0.11,"label":"Admitted tool adapters"}},"steps":[{"title":"Limit the reader’s authority","description":"The quarantined reader consumes the README with no tools and no credentials. Isolation removes direct action authority from this extraction step.","focus":["quarantine"]},{"title":"Validate structure before admission","description":"The adapter admits only a completed, schema-valid result. Incomplete or invalid extraction is not dispatched; valid structure alone still establishes no test success.","focus":["adapter","failure"]},{"title":"Keep claim and provenance distinct","description":"The admitted record separates claimed_tests_passed from host metadata such as source identity, version, and untrusted_external provenance. The planner sees a document claim, not a protected-runner result.","focus":["record","planner"]},{"title":"Resolve indirect content before use","description":"Even apply_patch with a typed handle reaches the reference monitor. The monitor resolves the stored bytes and admits the operation only under the applicable policy.","focus":["store","monitor","tools"]}],"artwork_reviewed":true,"art_sha1":"1f34e4d5f8a16ad3374737dc1f4687cca9d5a72c","art_kind":"svg","art_width":1200,"art_height":765,"art_structural_sha1":"114eb893449b8900ac50c0decf323866b55c1fe4"},"vol3:fig-vol3-radix-tree-cache":{"key":"vol3:fig-vol3-radix-tree-cache","figure_id":"fig-vol3-radix-tree-cache","source":"books/vol3/05_kv_cache/05_kv_cache.qmd","title":"Leaf-First Eviction in a Radix Prefix Cache","status":"ready","treatment":"annotated","question":"Which cached prefix can be evicted without breaking an active request?","scope":"The tree distinguishes cached dormant state from a running request’s path; leaf eligibility does not make every dormant ancestor evictable.","regions":{"active":{"x":0.02,"y":0.05,"w":0.39,"h":0.45,"label":"Active shared prefix and repair path"},"leaves":{"x":0.21,"y":0.375,"w":0.37,"h":0.105,"label":"Dormant leaf candidates"},"after":{"x":0.02,"y":0.57,"w":0.54,"h":0.42,"label":"Tree after leaf eviction"},"legend":{"x":0.6,"y":0.32,"w":0.39,"h":0.37,"label":"Cache-state legend"}},"steps":[{"title":"Shared ancestors remain useful","description":"The active repair path includes the shared prefix and repair history. These ancestors remain live even when other branches are dormant.","focus":["active","legend"]},{"title":"Choose an eligible leaf","description":"Rejected branch and Final turn are dormant leaves in the first panel. Leaf-first eviction avoids removing a prefix that still supports a retained descendant.","focus":["leaves"]},{"title":"Return blocks to the pool","description":"The second panel removes Final turn while preserving its Other task ancestor. Other task is now a dormant leaf and can become a later candidate.","focus":["after"]}],"artwork_reviewed":true,"art_sha1":"e8aa3cbb74a6a2d15a773c8f0cdf09998004809e","art_kind":"svg","art_width":1200,"art_height":845,"art_structural_sha1":"e8aa3cbb74a6a2d15a773c8f0cdf09998004809e"},"vol3:fig-vol3-recovery-decision-tree":{"key":"vol3:fig-vol3-recovery-decision-tree","figure_id":"fig-vol3-recovery-decision-tree","source":"books/vol3/12_failure_recovery/12_failure_recovery.qmd","title":"Recovery Decision Order","status":"ready","treatment":"annotated","question":"Why must recovery classify evidence and admissibility before comparing costs?","scope":"An unknown effect permits only the same-operation repeat contract. Result-recovery probes and waits gather evidence; they do not establish an outcome by assumption.","regions":{"evidence":{"x":0.035,"y":0.17,"w":0.75,"h":0.1,"label":"Classify evidence"},"unknown":{"x":0.035,"y":0.32,"w":0.2,"h":0.1,"label":"Unknown outcome branch"},"known":{"x":0.235,"y":0.32,"w":0.55,"h":0.1,"label":"Rejected or established branch"},"admissibility":{"x":0.035,"y":0.48,"w":0.75,"h":0.1,"label":"Authority, allowance, and deadline"},"cost":{"x":0.035,"y":0.665,"w":0.75,"h":0.115,"label":"Matched-endpoint cost comparison"},"actions":{"x":0.045,"y":0.845,"w":0.735,"h":0.13,"label":"Recovery choices"},"hold":{"x":0.79,"y":0.82,"w":0.19,"h":0.14,"label":"Hold or escalate"}},"steps":[{"title":"Classify what is known about the effect","description":"Outcome unknown restricts recovery to a retry under the same-operation contract. A rejected proposal or an established effect permits consideration of different proposals, repair, or compensation.","focus":["evidence","unknown","known"]},{"title":"Remove inadmissible choices","description":"Authority, allowance with finalization reserve intact, and deadline filter the candidates. With no admissible survivor, the runtime holds or escalates instead of buying a cheap unsafe action.","focus":["admissibility","hold"]},{"title":"Compare only matched endpoints","description":"Expected cost ranks the surviving choices for the same endpoint, separately in seconds and dollars. Cost ranking cannot authorize an otherwise forbidden recovery action.","focus":["cost","actions"]}],"artwork_reviewed":true,"art_sha1":"0baf608e962a5015cbd3eb124efd566af6d603b3","art_kind":"svg","art_width":1200,"art_height":705,"art_structural_sha1":"86a285ba9228864d4b9d65280be023904f66445f"},"vol3:fig-vol3-replay-mode":{"key":"vol3:fig-vol3-replay-mode","figure_id":"fig-vol3-replay-mode","source":"books/vol3/11_durable_execution/11_durable_execution.qmd","title":"Live Execution vs. Replay","status":"ready","treatment":"annotated","question":"How does replay inspect a trajectory without repeating its effects?","scope":"Replay follows recorded events and stops on an unlogged request; it is not a fresh sampling run.","regions":{"live":{"x":0.03,"y":0.07,"w":0.93,"h":0.26,"label":"Live execution path"},"liveLog":{"x":0.03,"y":0.34,"w":0.93,"h":0.15,"label":"Appended live events"},"replay":{"x":0.03,"y":0.6,"w":0.67,"h":0.16,"label":"Replay harness, stubbed model, authorization"},"tools":{"x":0.74,"y":0.57,"w":0.23,"h":0.21,"label":"Disconnected tools and stop gate"},"recorded":{"x":0.03,"y":0.84,"w":0.93,"h":0.14,"label":"Recorded events streamed in order"}},"steps":[{"title":"Live execution produces the record","description":"The live harness samples the model and authorizes tools with real effects. Each step appends its corresponding trajectory event.","focus":["live","liveLog"]},{"title":"Replay consumes the record","description":"The replay harness reads recorded events in order. The model is stubbed and tool execution is disconnected, so replay does not repeat external effects.","focus":["replay","recorded"]},{"title":"Stop beyond recorded behavior","description":"An unlogged request reaches a stop gate instead of a tool. Missing history remains a boundary of the replay, not permission to improvise a new action.","focus":["tools"]}],"artwork_reviewed":true,"art_sha1":"a1c1281d0a6de15c6ad97a1f185665bbe559ea40","art_kind":"svg","art_width":1200,"art_height":743,"art_structural_sha1":"77fcf40372ed132a8d3d60f450c8774a9a6fdfd5"},"vol3:fig-vol3-retrieval-contract":{"key":"vol3:fig-vol3-retrieval-contract","figure_id":"fig-vol3-retrieval-contract","source":"books/vol3/06_long_term_memory/06_long_term_memory.qmd","title":"The Retrieval Contract","status":"ready","treatment":"annotated","question":"What must a retrieval result disclose before entering context?","scope":"Access scope and revision are runtime bounds; a ranked hit is not automatically current or complete evidence.","regions":{"bounds":{"x":0.03,"y":0.16,"w":0.27,"h":0.32,"label":"Scoped revision filter"},"envelope":{"x":0.5,"y":0.03,"w":0.48,"h":0.55,"label":"Result envelope"},"runtime":{"x":0.09,"y":0.75,"w":0.27,"h":0.18,"label":"Runtime sets bounds"},"stage":{"x":0.5,"y":0.73,"w":0.3,"h":0.16,"label":"Evidence staging budget"},"next":{"x":0.82,"y":0.75,"w":0.15,"h":0.18,"label":"Next model call"}},"steps":[{"title":"Declare the search boundary","description":"The runtime supplies scope, version, and limits; the model may propose terms. The search excludes r17 and material outside the allowed scope.","focus":["runtime","bounds"]},{"title":"Read status before reading hits","description":"The envelope reports the searched scope and revision together with complete, partial, or unavailable status. Limits and continuation information qualify what the search established.","focus":["envelope"]},{"title":"Stage only the needed payload","description":"The runtime stages returned items under the active payload budget. Returned evidence keeps path, range, revision, and provenance.","focus":["stage"]},{"title":"Build a bounded next call","description":"The next model call receives selected evidence rather than an unqualified view of the entire repository. Search completeness and context selection remain separate properties.","focus":["envelope","next"]}],"artwork_reviewed":true,"art_sha1":"81b11a25c6f1d6eca2eeac6f21c9de2adc5ce33d","art_kind":"svg","art_width":1200,"art_height":734,"art_structural_sha1":"5946efeb7d74938a52401a851f22faad5a9b04c2"},"vol3:fig-vol3-saga-flow":{"key":"vol3:fig-vol3-saga-flow","figure_id":"fig-vol3-saga-flow","source":"books/vol3/12_failure_recovery/12_failure_recovery.qmd","title":"Registration Before Dispatch, Release After Evidence","status":"ready","treatment":"annotated","question":"How does cleanup remain owned when provisioning or release has an uncertain outcome?","scope":"Cleanup is compensation, not erasure of history. Target binding requires correlated evidence, and independent scratch removal is not a prerequisite for release.","regions":{"register":{"x":0.05,"y":0.1,"w":0.25,"h":0.14,"label":"Register cleanup obligation"},"dispatch":{"x":0.37,"y":0.1,"w":0.26,"h":0.14,"label":"Dispatch provisioning"},"unknown":{"x":0.38,"y":0.27,"w":0.25,"h":0.13,"label":"Lost reply leaves owned obligation"},"binding":{"x":0.69,"y":0.1,"w":0.26,"h":0.14,"label":"Bind target on evidence"},"predecessors":{"x":0.05,"y":0.6,"w":0.25,"h":0.23,"label":"Test ending and artifact preservation"},"release":{"x":0.39,"y":0.65,"w":0.23,"h":0.14,"label":"Registered release"},"outcomes":{"x":0.69,"y":0.6,"w":0.26,"h":0.23,"label":"Evidence-based closure or retention"}},"steps":[{"title":"Register before sending work","description":"The cleanup obligation exists before provision_test_env_r18 is dispatched. Its target remains unbound until the runtime receives correlated evidence.","focus":["register","dispatch"]},{"title":"Preserve uncertainty rather than guess","description":"A lost reply leaves an open, owned obligation. Evidence binding env_r18_01 supplies the target for the registered cleanup; lack of a reply supplies no substitute target.","focus":["unknown","binding"]},{"title":"Respect cleanup dependencies","description":"Release waits for the test to end or cancellation to be confirmed and for artifacts to be preserved outside the environment. Scratch removal is independent.","focus":["predecessors","release"]},{"title":"Close only on a demonstrated postcondition","description":"A confirmed release closes the obligation. An unconfirmed release leaves it retained and owned, so the recovery path never ends by assuming the environment is clean.","focus":["outcomes"]}],"artwork_reviewed":true,"art_sha1":"c624faad542a83d49cdd88bee6e6a4f6885546c5","art_kind":"svg","art_width":1200,"art_height":758,"art_structural_sha1":"dbcbe5ba800afbf0edfe4046cb566e4b8a6ceab9"},"vol3:fig-vol3-sample-size-confidence-intervals":{"key":"vol3:fig-vol3-sample-size-confidence-intervals","figure_id":"fig-vol3-sample-size-confidence-intervals","source":"books/vol3/13_evaluation/13_evaluation.qmd","title":"How Many Tasks an Interval Needs","status":"ready","treatment":"annotated","question":"Why can a small evaluation produce a misleadingly narrow interval?","scope":"Panel A is a normal-approximation sample-size model for independent tasks; panel B compares interval methods at fixed N = 50.","regions":{"size":{"x":0.02,"y":0.02,"w":0.49,"h":0.96,"label":"Sample-size and half-width curves"},"zero":{"x":0.57,"y":0.13,"w":0.42,"h":0.21,"label":"Zero accepted tasks"},"two":{"x":0.57,"y":0.42,"w":0.42,"h":0.23,"label":"Two accepted tasks"},"half":{"x":0.57,"y":0.72,"w":0.42,"h":0.25,"label":"Twenty-five accepted tasks"}},"steps":[{"title":"Precision costs independent tasks","description":"The left plot shows half-width shrinking as 1 over square root of N. The marked target makes clear that a small improvement in precision can demand many more tasks.","focus":["size"]},{"title":"Zero observed is not zero uncertainty","description":"For 0 of 50 accepted, the Wald interval collapses to zero width. Wilson retains a positive upper bound, acknowledging finite evidence.","focus":["zero"]},{"title":"Inspect behavior near a boundary","description":"At 2 of 50, Wald extends below zero while Wilson remains within the probability range. At 25 of 50 the two intervals are much closer.","focus":["two","half"]}],"artwork_reviewed":true,"art_sha1":"50e1585b41ec0991c8b8edcd123e10a9a1d26f48","art_kind":"svg","art_width":1200,"art_height":695,"art_structural_sha1":"50e1585b41ec0991c8b8edcd123e10a9a1d26f48"},"vol3:fig-vol3-sandbox-pool-lifecycle":{"key":"vol3:fig-vol3-sandbox-pool-lifecycle","figure_id":"fig-vol3-sandbox-pool-lifecycle","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"A Pooled Instance from Baseline to Reuse","status":"ready","treatment":"annotated","question":"What must finish before a pooled sandbox is safe to lease again?","scope":"Ending a trajectory taints its instance; reuse requires the reset contract, not merely process exit.","regions":{"lease":{"x":0.02,"y":0.02,"w":0.97,"h":0.16,"label":"Baseline, standby, leased, tainted"},"reclaim":{"x":0.7,"y":0.24,"w":0.28,"h":0.64,"label":"Ordered reclaim protocol"},"destroy":{"x":0.45,"y":0.5,"w":0.2,"h":0.16,"label":"Destroy on failure"},"return":{"x":0.3,"y":0.9,"w":0.54,"h":0.07,"label":"Return to standby after checks"}},"steps":[{"title":"Lease from a trusted baseline","description":"A restored instance begins in clean, unassigned standby before one trajectory leases it. End of that trajectory marks it tainted.","focus":["lease"]},{"title":"Remove authority before reset","description":"Reclamation fences authority, quiesces owned work, and exports only permitted outputs before discarding or restoring state. This ordering prevents lingering work from writing into a reused instance.","focus":["reclaim"]},{"title":"Verify or retire","description":"Only passing reset-contract checks returns an instance to standby. A failed reclaim step leads to destruction rather than optimistic reuse.","focus":["reclaim","destroy","return"]}],"artwork_reviewed":true,"art_sha1":"5cc76cd5caee4045bf914182ca06164ea3e4edb2","art_kind":"svg","art_width":1200,"art_height":590,"art_structural_sha1":"599e730dea4fff14eb0c387555273d162a0de01d"},"vol3:fig-vol3-scaffold-spread":{"key":"vol3:fig-vol3-scaffold-spread","figure_id":"fig-vol3-scaffold-spread","source":"books/vol3/13_evaluation/13_evaluation.qmd","title":"One Model, Many Scaffolds","status":"ready","treatment":"annotated","question":"Why does a benchmark score describe an agent configuration rather than just its model?","scope":"Rows combine reported configurations on the same benchmark. Their min–max spans are observed scaffold spreads, not confidence intervals or causal estimates of scaffold quality.","regions":{"legend":{"x":0.2,"y":0.03,"w":0.56,"h":0.15,"label":"Scaffold marker legend"},"opus":{"x":0.1,"y":0.18,"w":0.83,"h":0.09,"label":"Claude Opus 4.6 scaffold spread"},"upper":{"x":0.1,"y":0.05,"w":0.83,"h":0.39,"label":"Higher-median model rows"},"lower":{"x":0.1,"y":0.47,"w":0.83,"h":0.45,"label":"Other model scaffold spreads"}},"steps":[{"title":"Hold the model row fixed","description":"Each dot on a row is the same model inside a different scaffold. Red diamonds identify the benchmark reference scaffold; the light bar spans the reported minimum and maximum.","focus":["legend","opus"]},{"title":"Inspect a concrete within-model range","description":"The annotated Claude Opus 4.6 row runs from 58 to 80 percent. That spread demonstrates why naming only the model omits a consequential part of the evaluated system.","focus":["opus"]},{"title":"Compare configurations with their context","description":"Across rows, within-model scaffold spreads can rival differences between models. Report the harness, scaffold, and acceptance procedure alongside the score rather than treating row order as an intrinsic model ranking.","focus":["upper","lower"]}],"artwork_reviewed":true,"art_sha1":"4b5549885b22c65fd69b66de18487cceb3a4118c","art_kind":"png","art_width":4701,"art_height":2974},"vol3:fig-vol3-search-topologies":{"key":"vol3:fig-vol3-search-topologies","figure_id":"fig-vol3-search-topologies","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Where Each Search Structure Prunes","status":"ready","treatment":"annotated","question":"When does each search topology discard work, and what information guides its next expansion?","scope":"Pool sizes, beam widths, and depths are illustrative. The diagrams imply neither equal compute cost nor guaranteed useful pruning.","regions":{"best":{"x":0.02,"y":0.03,"w":0.31,"h":0.82,"label":"Best-of-N complete candidates"},"beam":{"x":0.35,"y":0.03,"w":0.31,"h":0.82,"label":"Beam step boundaries"},"tree":{"x":0.68,"y":0.03,"w":0.31,"h":0.82,"label":"Tree selection and path update"},"legend":{"x":0.03,"y":0.88,"w":0.96,"h":0.1,"label":"Generated, retained, pruned, and unexpanded states"}},"steps":[{"title":"Best-of-N chooses after completion","description":"Each sampled path reaches a complete candidate before selection discards the others. The crossed endpoints record generated work that is no longer retained.","focus":["best"]},{"title":"Beam search prunes during generation","description":"At each marked step boundary, scoring retains two continuations in this example. Pruning changes which partial candidates can receive subsequent work.","focus":["beam"]},{"title":"Tree search revisits a selected path","description":"A selection rule chooses a leaf to expand and evaluate. The bold path carries the updated visit counts and value estimates back toward the root.","focus":["tree"]},{"title":"Distinguish discarded from ungenerated work","description":"Crossed nodes were generated and then pruned; dotted nodes were not expanded. Both reduce the visible frontier, but their compute histories differ.","focus":["legend","tree"]}],"artwork_reviewed":true,"art_sha1":"03ed2f0e08106904d712b7f9e1505e63b62f071b","art_kind":"svg","art_width":1200,"art_height":597,"art_structural_sha1":"03ed2f0e08106904d712b7f9e1505e63b62f071b"},"vol3:fig-vol3-semantic-watchdog":{"key":"vol3:fig-vol3-semantic-watchdog","figure_id":"fig-vol3-semantic-watchdog","source":"books/vol3/12_failure_recovery/12_failure_recovery.qmd","title":"From Recurrence to Guarded Response","status":"ready","treatment":"annotated","question":"How does repeated candidate state become an enforced admission hold?","scope":"Equal digests establish equality only of the captured projection. Deliberate backtracking can recur, and policy chooses among responses without a fixed escalation order.","regions":{"versions":{"x":0.175,"y":0.135,"w":0.765,"h":0.13,"label":"Alternating candidate versions"},"digests":{"x":0.195,"y":0.31,"w":0.73,"h":0.08,"label":"Retained state digests"},"recurrence":{"x":0.44,"y":0.395,"w":0.49,"h":0.11,"label":"Period-two recurrence finding"},"finding":{"x":0.045,"y":0.715,"w":0.195,"h":0.11,"label":"Recorded observations and rule"},"hold":{"x":0.295,"y":0.715,"w":0.195,"h":0.11,"label":"Admission hold"},"responses":{"x":0.62,"y":0.65,"w":0.33,"h":0.28,"label":"Three policy-selected responses"}},"steps":[{"title":"Observe the recurring projection","description":"The four captured revisions alternate A, B, A, B with the same test failure. Their digests reflect the recorded state projection rather than every property of the whole environment.","focus":["versions","digests"]},{"title":"Record the supported recurrence","description":"The two highlighted b digests are two positions apart. The retained window supports a period-two finding with explicit observations and detection rule.","focus":["digests","recurrence","finding"]},{"title":"Make the finding constrain admission","description":"The finding causes an admission hold that withholds new ordinary work. Merely inserting a prompt warning would not enforce this boundary.","focus":["finding","hold"]},{"title":"Choose a guarded response","description":"Policy selects bounded diagnostic continuation, controlled backtrack, or ending model-directed repair. These are alternatives, not a mandatory three-step sequence.","focus":["responses"]}],"artwork_reviewed":true,"art_sha1":"2aa790ecef21c0950bcd25ff3ea88e16ca812a15","art_kind":"svg","art_width":1200,"art_height":762,"art_structural_sha1":"ffefb86a087d93c4ef3b4df3aefe5933ce82ffb5"},"vol3:fig-vol3-step-ceiling-curves":{"key":"vol3:fig-vol3-step-ceiling-curves","figure_id":"fig-vol3-step-ceiling-curves","source":"books/vol3/10_agent_harness/10_agent_harness.qmd","title":"Raising the Ceiling Helps Some Models, Not Others","status":"ready","treatment":"annotated","question":"Which models benefit when the enforced action ceiling increases?","scope":"The points are benchmark observations at three enforced ceilings. Connecting lines do not measure intermediate ceilings or establish a universal optimal budget.","regions":{"early":{"x":0.11,"y":0.33,"w":0.26,"h":0.47,"label":"15-to-50-step observations"},"gain":{"x":0.35,"y":0.1,"w":0.53,"h":0.11,"label":"Sonnet 4.5 continuing gain"},"flat":{"x":0.35,"y":0.33,"w":0.61,"h":0.2,"label":"Flattening or dipping models"},"o3":{"x":0.35,"y":0.57,"w":0.39,"h":0.12,"label":"o3 continuing gain"},"axis":{"x":0.1,"y":0.86,"w":0.6,"h":0.12,"label":"Enforced step ceilings"}},"steps":[{"title":"Identify the intervention","description":"The horizontal axis lists enforced limits of 15, 50, and 100 actions. Each curve holds the named model fixed while the allowed action budget changes.","focus":["axis","early"]},{"title":"Find continuing benefit","description":"The Sonnet 4.5 curve continues upward from 50 to 100 actions. For this measured configuration, additional opportunity still leads to more completed tasks.","focus":["gain"]},{"title":"Find diminishing or negative return","description":"Sonnet 4, Sonnet 3.7, and computer-use-preview flatten or dip over the same interval. Extra actions do not uniformly improve task success.","focus":["flat"]},{"title":"Separate success rate from budget response","description":"o3 starts lower but continues gaining. A model’s absolute success rate and its marginal response to a larger ceiling are different properties to measure.","focus":["o3"]}],"artwork_reviewed":true,"art_sha1":"c5f79312c5ad163caa86fc122a5a6ce30648a850","art_kind":"png","art_width":3650,"art_height":2267},"vol3:fig-vol3-stochastic-computer-map":{"key":"vol3:fig-vol3-stochastic-computer-map","figure_id":"fig-vol3-stochastic-computer-map","source":"books/vol3/01_introduction/01_introduction.qmd","title":"The Stochastic Computer as an Architectural Map","status":"ready","treatment":"annotated","question":"How does one live trajectory differ from learning across tasks?","scope":"The approximate computer analogy is an introductory map; model proposals do not inherit processor correctness or execution authority.","regions":{"model":{"x":0.08,"y":0.08,"w":0.37,"h":0.14,"label":"Model"},"memory":{"x":0.53,"y":0.08,"w":0.38,"h":0.14,"label":"Agent memory"},"runtime":{"x":0.08,"y":0.31,"w":0.83,"h":0.13,"label":"Agent runtime"},"tools":{"x":0.08,"y":0.52,"w":0.83,"h":0.15,"label":"Tools and environment"},"learning":{"x":0.06,"y":0.77,"w":0.86,"h":0.2,"label":"Across-task activities"}},"steps":[{"title":"Proposals and stored state","description":"The model and agent memory sit in the live execution band. Context and stored-state exchanges pass through the runtime.","focus":["model","memory","runtime"]},{"title":"The runtime mediates effects","description":"Validated calls reach tool use; tools exchange effects and results with the environment. The model does not bypass this path.","focus":["runtime","tools"]},{"title":"Across-task changes","description":"Evaluated trajectories feed learning, which can return updated weights. Coordinating many trajectories is a distinct across-task activity, rather than another step of one model call.","focus":["learning"]}],"artwork_reviewed":true,"art_sha1":"b7e6454eaf88a2a44b716036b3cb60c98bf7d4fd","art_kind":"svg","art_width":1200,"art_height":810,"art_structural_sha1":"7101904835cc0a1f9ee3c06b6f714b8097fad49f"},"vol3:fig-vol3-stopping-boundaries":{"key":"vol3:fig-vol3-stopping-boundaries","figure_id":"fig-vol3-stopping-boundaries","source":"books/vol3/03_test_time_compute/03_test_time_compute.qmd","title":"Stopping Precedence","status":"ready","treatment":"annotated","question":"Which stopping condition takes precedence before the runtime admits more search work?","scope":"Stopping search does not make the acceptance decision. Hard ceilings stop new admissions even if further work appears valuable.","regions":{"ceiling":{"x":0.035,"y":0.08,"w":0.6,"h":0.12,"label":"Hard ceilings"},"acceptance":{"x":0.075,"y":0.255,"w":0.53,"h":0.09,"label":"Acceptance criteria"},"marginal":{"x":0.11,"y":0.38,"w":0.46,"h":0.14,"label":"Marginal gain rule"},"admit":{"x":0.21,"y":0.575,"w":0.245,"h":0.13,"label":"Admit next work"},"hardstop":{"x":0.69,"y":0.08,"w":0.29,"h":0.21,"label":"Stop new work"},"accepted":{"x":0.69,"y":0.375,"w":0.29,"h":0.21,"label":"Stop search for acceptance decision"},"early":{"x":0.69,"y":0.67,"w":0.29,"h":0.21,"label":"Stop early without acceptable candidate"}},"steps":[{"title":"Apply hard ceilings first","description":"Tokens, calls, depth, and time bound new work. At a ceiling, the runtime preserves an already acceptable candidate; otherwise it escalates.","focus":["ceiling","hardstop"]},{"title":"End search when criteria are met","description":"Within the hard limits, meeting acceptance criteria ends search and sends the candidate to the acceptance decision. This step does not replace that decision.","focus":["acceptance","accepted"]},{"title":"Price only the remaining work","description":"Only after the first two tests does the marginal rule compare gain per cost with the stopping threshold. Insufficient gain ends the attempt as incomplete or escalated.","focus":["marginal","early"]},{"title":"Admit the next bounded increment","description":"The inner loop reaches Admit next work only when all three conditions permit continuation. The runtime repeats the checks before admitting later increments.","focus":["admit"]}],"artwork_reviewed":true,"art_sha1":"fb1ff14bbb8029121a44299f15308544fb6b9c69","art_kind":"svg","art_width":1200,"art_height":537,"art_structural_sha1":"1e7af6edd97c652126b05ace29785b6755c3c4ac"},"vol3:fig-vol3-stream-ingestion":{"key":"vol3:fig-vol3-stream-ingestion","figure_id":"fig-vol3-stream-ingestion","source":"books/vol3/07_tool_calling/07_tool_calling.qmd","title":"Bounded capture before staging","status":"ready","treatment":"annotated","question":"How can a tool adapter drain an arbitrarily long output stream while keeping capture memory bounded?","scope":"Capture and staged-observation budgets count bytes, while the next model call is measured in tokens. Raw-record retention and later range reads require authorization.","regions":{"pipes":{"x":0.02,"y":0.07,"w":0.21,"h":0.62,"label":"Child process and bounded pipes"},"head":{"x":0.26,"y":0.15,"w":0.1,"h":0.48,"label":"Head fills once"},"middle":{"x":0.345,"y":0.15,"w":0.3,"h":0.48,"label":"Middle bytes counted, not kept"},"tail":{"x":0.63,"y":0.15,"w":0.12,"h":0.51,"label":"Tail ring overwrites oldest"},"record":{"x":0.03,"y":0.81,"w":0.19,"h":0.14,"label":"Authorized retained record"},"staged":{"x":0.78,"y":0.09,"w":0.2,"h":0.61,"label":"Bounded staged observation"},"model":{"x":0.795,"y":0.795,"w":0.175,"h":0.155,"label":"Next model call"}},"steps":[{"title":"Drain both channels under limits","description":"One readiness loop drains stdout and stderr, enforcing a byte limit and deadline. Draining both pipes prevents one full channel from stalling the child process.","focus":["pipes"]},{"title":"Keep a fixed head and rolling tail","description":"The head fills once. The tail ring replaces its oldest bytes as new output arrives, so longer output does not require a larger capture buffer.","focus":["head","tail"]},{"title":"Count the missing middle honestly","description":"Middle bytes are counted without being kept in capture memory. The omission notice describes that measured gap rather than pretending the staged output is complete.","focus":["middle","staged"]},{"title":"Stage a bounded observation","description":"Status, head, omission notice, tail, and a handle form the observation. The model’s token budget is a separate constraint from this byte budget.","focus":["staged","model"]},{"title":"Retrieve ranges only when permitted","description":"An authorized retained record may support later range reads by handle. That optional store is separate from the fixed-size capture buffers.","focus":["record"]}],"artwork_reviewed":true,"art_sha1":"bfbe4c0badb38b0039dc7e217bb7b662176b440f","art_kind":"svg","art_width":1200,"art_height":506,"art_structural_sha1":"3cca07bac031884919c43095f13e006c56a794d6"},"vol3:fig-vol3-streaming-cancellation":{"key":"vol3:fig-vol3-streaming-cancellation","figure_id":"fig-vol3-streaming-cancellation","source":"books/vol3/02_foundation_model/02_foundation_model.qmd","title":"Reject, Then Cancel","status":"ready","treatment":"annotated","question":"What does rejecting a stream guarantee, and what still depends on the service?","scope":"The allowance is 4,096 steps and the pictured rejection is at step 96; avoided service work is conditional.","regions":{"budget":{"x":0.18,"y":0.03,"w":0.8,"h":0.16,"label":"Service output allowance"},"prefix":{"x":0.18,"y":0.28,"w":0.46,"h":0.15,"label":"Held prefix and invalid key"},"reject":{"x":0.46,"y":0.49,"w":0.19,"h":0.15,"label":"Runtime rejection"},"local":{"x":0.18,"y":0.66,"w":0.47,"h":0.29,"label":"Unconditional runtime outcomes"},"remote":{"x":0.69,"y":0.66,"w":0.29,"h":0.29,"label":"Conditional service outcomes"}},"steps":[{"title":"Hold prefixes while parsing","description":"The runtime advances its parser without dispatching incomplete output. At step 96 the force key violates the schema.","focus":["prefix"]},{"title":"Reject locally and request cancellation","description":"The runtime records rejection and discards the partial proposal, then asks the service to cancel. Local refusal does not require a successful remote cancellation.","focus":["reject","local"]},{"title":"Read the conditional saving","description":"The long dashed allowance represents up to 4,000 steps not run, not guaranteed saved execution. It depends on the service receiving and honoring the request.","focus":["budget","remote"]},{"title":"Keep the two outcomes separate","description":"The payload remains undispatched even if remote decoding continues. Batch departure and KV-cache release belong to the honored-cancellation branch.","focus":["local","remote"]}],"artwork_reviewed":true,"art_sha1":"b8418a33f9fbfedac005accc852986a75ca7763d","art_kind":"svg","art_width":1200,"art_height":604,"art_structural_sha1":"968d29c7ff123b7b4f39f5999602a18fe0db4821"},"vol3:fig-vol3-supervisor-tree-isolation":{"key":"vol3:fig-vol3-supervisor-tree-isolation","figure_id":"fig-vol3-supervisor-tree-isolation","source":"books/vol3/18_multi_agent/18_multi_agent.qmd","title":"Restart Policies in a Supervision Tree","status":"ready","treatment":"annotated","question":"How should restart scope follow worker dependencies?","scope":"Restarts are fresh admitted attempts. They do not erase external effects or bypass cancellation cleanup.","regions":{"parent":{"x":0.36,"y":0.04,"w":0.22,"h":0.12,"label":"Parent supervisor"},"one":{"x":0.02,"y":0.24,"w":0.47,"h":0.72,"label":"One-for-one group"},"all":{"x":0.51,"y":0.24,"w":0.47,"h":0.72,"label":"One-for-all group"},"escalate":{"x":0.57,"y":0.03,"w":0.42,"h":0.35,"label":"Restart-intensity escalation"}},"steps":[{"title":"Independent siblings continue","description":"In the one-for-one card, only the failed middle worker lies inside the blast radius. Its restart creates a new attempt with its own reservation.","focus":["one"]},{"title":"Coupled siblings stop together","description":"In the one-for-all card, the caller failure invalidates the coupled interface and test work. Cancellation stops those siblings before the group restarts from recorded inputs.","focus":["all"]},{"title":"Bound repeated recovery","description":"When declared restart intensity is exceeded, local restarting stops and failure escalates to the parent. More retries are not an unbounded recovery policy.","focus":["escalate","parent"]}],"artwork_reviewed":true,"art_sha1":"0d47e496a9c4a0b2459800451f08ea10ff28c066","art_kind":"svg","art_width":1200,"art_height":638,"art_structural_sha1":"5e677ee1123c7744f78318d2d4d19907eff5f35f"},"vol3:fig-vol3-swapping-tradeoff":{"key":"vol3:fig-vol3-swapping-tradeoff","figure_id":"fig-vol3-swapping-tradeoff","source":"books/vol3/05_kv_cache/05_kv_cache.qmd","title":"Keep, Offload, or Park a Paused Trajectory","status":"ready","treatment":"annotated","question":"When should a paused trajectory retain or offload its KV state?","scope":"This is the figure’s illustrative decision model with logarithmic axes, not a measured scheduler policy for every machine.","regions":{"retain":{"x":0.13,"y":0.04,"w":0.28,"h":0.71,"label":"Retain region"},"offload":{"x":0.41,"y":0.04,"w":0.33,"h":0.71,"label":"Host-memory offload region"},"park":{"x":0.75,"y":0.04,"w":0.23,"h":0.71,"label":"Park or drop region"},"example":{"x":0.32,"y":0.27,"w":0.43,"h":0.28,"label":"Worked example and round-trip boundary"}},"steps":[{"title":"Compare wait with transfer","description":"The sloped boundary compares expected wait with the KV round-trip transfer time. On the retain side, transferring out and back costs more than the wait.","focus":["retain","example"]},{"title":"Free device capacity during a long wait","description":"Beyond the transfer boundary, the diagram favors offloading to host memory. The worked example locates one context and wait on this side.","focus":["offload","example"]},{"title":"Host memory is finite too","description":"The right-hand boundary introduces host-memory pressure. Very long waits may require parking on flash or dropping state and later recomputing it.","focus":["park"]}],"artwork_reviewed":true,"art_sha1":"d015de79ca8543d0748f729d3d451004e5f8659d","art_kind":"svg","art_width":1200,"art_height":550,"art_structural_sha1":"c2894757d9933899def5e1acc064f0a703166500"},"vol3:fig-vol3-tail-sampling-pipeline":{"key":"vol3:fig-vol3-tail-sampling-pipeline","figure_id":"fig-vol3-tail-sampling-pipeline","source":"books/vol3/14_agent_operations/14_agent_operations.qmd","title":"Verdict-Aware Trace Selection","status":"ready","treatment":"annotated","question":"Why must evaluation accounting survive discarded traces?","scope":"Tail selection preserves diagnostic detail selectively; it cannot repair records lost before capture.","regions":{"capture":{"x":0.02,"y":0.28,"w":0.21,"h":0.35,"label":"Admitted trials and capture boundary"},"buffer":{"x":0.26,"y":0.24,"w":0.29,"h":0.24,"label":"Bounded staging buffer"},"selection":{"x":0.58,"y":0.12,"w":0.29,"h":0.51,"label":"Verdict-aware selection"},"trace":{"x":0.9,"y":0.17,"w":0.08,"h":0.26,"label":"Selected trace storage"},"discard":{"x":0.88,"y":0.65,"w":0.1,"h":0.12,"label":"Unselected detail"},"account":{"x":0.02,"y":0.81,"w":0.96,"h":0.15,"label":"Complete accounting outside buffer"}},"steps":[{"title":"Capture under explicit limits","description":"Admitted trials enter through a minimizing and redacting capture boundary. Trace detail waits in a bounded buffer for late task verdicts.","focus":["capture","buffer"]},{"title":"Select with precedence","description":"Failure or violation evidence takes priority, followed by pending or unknown outcomes and selected accepted runs. The priorities govern retained detail, not which trials existed.","focus":["selection"]},{"title":"Acknowledge diagnostic losses","description":"Selected traces reach the trace store; other detail is discarded, and buffer pressure can cause eviction. Tail selection does not eliminate staging memory or ingress.","focus":["trace","discard","buffer"]},{"title":"Keep the denominator separately","description":"Every trial and recorded drop, eviction, or truncation reaches the accounting record outside the buffer. Evaluation rates must not use only the retained traces as their cohort.","focus":["account"]}],"artwork_reviewed":true,"art_sha1":"50738a9032db08d37c5ce3e73ceb5d68eacedc90","art_kind":"svg","art_width":1200,"art_height":664,"art_structural_sha1":"7b128158192b99b6bf4c4f706a63970adc7ce27c"},"vol3:fig-vol3-taint-tracking-pipeline":{"key":"vol3:fig-vol3-taint-tracking-pipeline","figure_id":"fig-vol3-taint-tracking-pipeline","source":"books/vol3/09_security/09_security.qmd","title":"Two Labels, Two Independent Checks","status":"ready","treatment":"annotated","question":"Why does a fixture-dependent search fail release while a README-derived test claim independently fails evidence policy?","scope":"Integrity provenance and confidentiality are independent labels, not one trust score. The conservative invocation policy tracks possible dependence on all inputs it saw.","regions":{"inputs":{"x":0.02,"y":0.06,"w":0.23,"h":0.43,"label":"README and private-fixture labels"},"planner":{"x":0.265,"y":0.18,"w":0.14,"h":0.2,"label":"Planner invocation"},"derived":{"x":0.425,"y":0.06,"w":0.265,"h":0.43,"label":"Union provenance and intersection recipients"},"release":{"x":0.72,"y":0.11,"w":0.245,"h":0.41,"label":"Release check"},"claim":{"x":0.02,"y":0.64,"w":0.67,"h":0.18,"label":"README-derived test assertion"},"evidence":{"x":0.72,"y":0.53,"w":0.245,"h":0.42,"label":"Evidence check"}},"steps":[{"title":"Combine dependencies conservatively","description":"The planner invocation sees both the README and fixture. Its derived query carries the union of their provenance and the intersection of their permitted recipients.","focus":["inputs","planner","derived"]},{"title":"Reject a recipient outside the label","description":"The query permits the local test runner, while package_search resolves to the external search endpoint. The release check therefore rejects the query before dispatch.","focus":["derived","release"]},{"title":"Refuse an unsupported pass claim","description":"The extracted claimed_tests_passed value comes from readme_7. Recording an acceptance test pass admits only protected-runner influence, so the separate evidence check refuses this claim.","focus":["claim","evidence"]}],"artwork_reviewed":true,"art_sha1":"d11dbf5f19b77aa35bca81cebc96a7f6a7f7afdc","art_kind":"svg","art_width":1200,"art_height":615,"art_structural_sha1":"d3d18a622c13a40760b30464c726cb31abb5814a"},"vol3:fig-vol3-threat-model":{"key":"vol3:fig-vol3-threat-model","figure_id":"fig-vol3-threat-model","source":"books/vol3/08_sandboxes/08_sandboxes.qmd","title":"Where Each Boundary Acts","status":"ready","treatment":"annotated","question":"Why can a permitted tool still disclose protected information?","scope":"The figure contrasts a blocked injected shell request with a permitted reporting channel; passing one control is not whole-system safety.","regions":{"inject":{"x":0.02,"y":0.34,"w":0.2,"h":0.21,"label":"Injected shell request"},"mediators":{"x":0.3,"y":0.07,"w":0.44,"h":0.59,"label":"Mediation, execution, egress boundaries"},"denied":{"x":0.78,"y":0.34,"w":0.2,"h":0.21,"label":"Unreached diagnostics"},"report":{"x":0.02,"y":0.67,"w":0.96,"h":0.21,"label":"Permitted reporting disclosure"}},"steps":[{"title":"Admission is only the first boundary","description":"The injected shell request passes mediation but encounters a filesystem read denial. Different controls act on different capabilities.","focus":["inject","mediators"]},{"title":"A blocked path stays blocked","description":"The diagnostics destination is not reached along the injected path. The marked upload denial adds a separate egress boundary.","focus":["mediators","denied"]},{"title":"Permitted does not mean harmless","description":"The submit_report channel is admitted, reads allowed data, and reaches an approved service. Disclosure can still occur through this permitted channel, so policy must consider fields and information flow.","focus":["report"]}],"artwork_reviewed":true,"art_sha1":"81d4b04f43d4ea9d77e377a21d2dce391e0e2e39","art_kind":"svg","art_width":1200,"art_height":463,"art_structural_sha1":"d7649ef5dc214bd818cd59fcf580a1947ba3099a"},"vol3:fig-vol3-token-ast-mismatch":{"key":"vol3:fig-vol3-token-ast-mismatch","figure_id":"fig-vol3-token-ast-mismatch","source":"books/vol3/02_foundation_model/02_foundation_model.qmd","title":"One Keyword, Two Token Sequences","status":"ready","treatment":"annotated","question":"Why can four spaces change the token budget?","scope":"The printed IDs are specific to cl100k_base; they are not a universal tokenizer rule.","regions":{"plain":{"x":0.29,"y":0.11,"w":0.6,"h":0.18,"label":"Unindented lexer and characters"},"five":{"x":0.29,"y":0.31,"w":0.7,"h":0.13,"label":"Five byte-pair tokens"},"indent":{"x":0.18,"y":0.52,"w":0.72,"h":0.17,"label":"Indentation and lexer"},"leading":{"x":0.18,"y":0.71,"w":0.23,"h":0.22,"label":"Changed leading tokens"},"shared":{"x":0.41,"y":0.71,"w":0.49,"h":0.22,"label":"Four shared tokens"}},"steps":[{"title":"Start from the same source line","description":"The unindented lexer identifies def and get_user_id as language structure. The byte-pair row instead splits the line into five vocabulary items.","focus":["plain","five"]},{"title":"Add an indentation boundary","description":"The compiler records an indent separately from def. Its structural boundary is the dashed vertical line.","focus":["indent"]},{"title":"Find the space absorbed into def","description":"The indented byte-pair sequence starts with token 262 and token 711. Token 711 crosses the lexer boundary because the fourth space joins def.","focus":["leading"]},{"title":"Count the actual serialized sequence","description":"Only the four trailing tokens remain shared. The total changes from five to six, so character counts and compiler tokens cannot replace model-specific token counting.","focus":["five","shared"]}],"artwork_reviewed":true,"art_sha1":"2a9f1c0816ca76ebbd04150f3f8860738da330d5","art_kind":"svg","art_width":1200,"art_height":614,"art_structural_sha1":"2a9f1c0816ca76ebbd04150f3f8860738da330d5"},"vol3:fig-vol3-tool-call-loop":{"key":"vol3:fig-vol3-tool-call-loop","figure_id":"fig-vol3-tool-call-loop","source":"books/vol3/07_tool_calling/07_tool_calling.qmd","title":"The tool-call loop","status":"ready","treatment":"annotated","question":"How does one model turn become bounded observations without dispatching invalid or unauthorized calls?","scope":"The diagram separates pre-dispatch rejection from effect tracking. A dispatched operation with an unknown effect must remain unknown in its observation.","regions":{"model":{"x":0.02,"y":0.09,"w":0.17,"h":0.29,"label":"Proposed calls and identifiers"},"validate":{"x":0.24,"y":0.13,"w":0.15,"h":0.16,"label":"Validate schema"},"authorize":{"x":0.41,"y":0.13,"w":0.15,"h":0.16,"label":"Authorize grant"},"effect":{"x":0.58,"y":0.13,"w":0.4,"h":0.44,"label":"Dispatch and tool effect"},"shape":{"x":0.58,"y":0.42,"w":0.15,"h":0.16,"label":"Shape and match identifier"},"observations":{"x":0.22,"y":0.73,"w":0.54,"h":0.23,"label":"One observation per call ID"}},"steps":[{"title":"Identify every proposal","description":"The model proposes call_1, call_2, and call_3 in the same turn. Each identifier needs a corresponding observation for the next turn.","focus":["model"]},{"title":"Reject before dispatch when required","description":"Schema validation rejects call_3, and authorization rejects call_2. Their error observations return without claiming any tool effect occurred.","focus":["validate","authorize","observations"]},{"title":"Track the dispatched call","description":"Only the permitted call reaches the tool or environment. Dispatch must track the available outcome; sending a request alone does not prove completion.","focus":["effect"]},{"title":"Return bounded, correlated observations","description":"Shape bounds the tool return and matches its call ID. The next turn receives call_1’s result and the two rejection errors, preserving each proposal’s identity.","focus":["shape","observations"]}],"artwork_reviewed":true,"art_sha1":"5b63d68f9c173ae06292d8a7ddbb4d181fc40246","art_kind":"svg","art_width":1200,"art_height":640,"art_structural_sha1":"c806e32c0c23a261b392d13ced008fdcea096e9b"},"vol3:fig-vol3-trajectory-composition":{"key":"vol3:fig-vol3-trajectory-composition","figure_id":"fig-vol3-trajectory-composition","source":"books/vol3/16_fine_tuning/16_fine_tuning.qmd","title":"Observations Dominate Recorded Trajectories","status":"ready","treatment":"annotated","question":"Why is transcript volume larger than eligible policy supervision?","scope":"Bars measure pooled transcript characters with each message counted once, not tokenizer counts, repeated prompt ingestion, or compute spent.","regions":{"prompt":{"x":0.3,"y":0.06,"w":0.14,"h":0.1,"label":"First configuration prompt"},"observations":{"x":0.44,"y":0.06,"w":0.45,"h":0.1,"label":"First configuration observations"},"model":{"x":0.89,"y":0.06,"w":0.09,"h":0.1,"label":"First configuration model output"},"second":{"x":0.3,"y":0.19,"w":0.68,"h":0.11,"label":"Observation-heavy second configuration"},"fourth":{"x":0.3,"y":0.45,"w":0.68,"h":0.12,"label":"Largest printed model-output share"},"legend":{"x":0.46,"y":0.91,"w":0.4,"h":0.07,"label":"Role legend and character units"}},"steps":[{"title":"Partition one recorded transcript","description":"The first bar separates supplied prompt, environment observations, and generated model output. The three shares describe characters in the stored record.","focus":["prompt","observations","model"]},{"title":"Find where most storage comes from","description":"The second configuration’s long green region shows observations dominating its transcript. Tool output can occupy most of the record without being a policy action to imitate.","focus":["second"]},{"title":"Distinguish eligibility from selection","description":"The fourth configuration has a larger dark model-output share, but not every generated token is a valid training target. Refused or incorrect proposals still require target selection.","focus":["fourth"]},{"title":"Keep the measurement denominator","description":"The legend and axis describe character shares, chosen because tokenizers differ across configurations. These bars cannot be read directly as token budgets or training compute fractions.","focus":["legend"]}],"artwork_reviewed":true,"art_sha1":"82ba7f99af92a74031e622de76a6a0fbf198f437","art_kind":"png","art_width":5520,"art_height":2116},"vol3:fig-vol3-trajectory-typology":{"key":"vol3:fig-vol3-trajectory-typology","figure_id":"fig-vol3-trajectory-typology","source":"books/vol3/15_trajectory_curation/15_trajectory_curation.qmd","title":"Record Roles and Selected Targets","status":"ready","treatment":"annotated","question":"Which events become imitation targets, and which remain context or negative evidence?","scope":"Selection is per target, not an endorsement of every event in a successful trajectory. The hard-negative diagram records uncertainty about the first causal failure.","regions":{"direct":{"x":0.02,"y":0.03,"w":0.82,"h":0.23,"label":"Direct-success targets"},"recovery":{"x":0.02,"y":0.33,"w":0.96,"h":0.24,"label":"Recovery context and targets"},"negative":{"x":0.02,"y":0.65,"w":0.66,"h":0.24,"label":"Hard-negative candidate"},"legend":{"x":0.02,"y":0.9,"w":0.96,"h":0.075,"label":"Target, context, deficient, and loss-mask legend"}},"steps":[{"title":"Separate targets from supporting observations","description":"In the direct-success demonstration, inspect, edit, and report are selected targets. The task context and required-check observation support them without becoming imitation targets.","focus":["direct"]},{"title":"Retain the refused edit as recovery context","description":"The malformed proposal at e2 is deficient and never imitated. Inspecting the schema at e3, making the permitted edit at e4, and reporting scoped results at e6 become targets; the e5 check summary stays context.","focus":["recovery"]},{"title":"Keep plausible failures out of imitation","description":"The hard-negative edit passes a targeted check but fails a required check. Its deficient response is not an imitation target, and the recorded basis does not pretend the first causal failure is known exactly.","focus":["negative"]},{"title":"Read the loss mask explicitly","description":"The blue bars identify selected learning targets. A successful final outcome cannot replace this event-level decision about what behavior the learner should reproduce.","focus":["legend","recovery"]}],"artwork_reviewed":true,"art_sha1":"d0dccbd622c54bcb9bbf694e3382839909b87eb3","art_kind":"svg","art_width":1200,"art_height":703,"art_structural_sha1":"d0dccbd622c54bcb9bbf694e3382839909b87eb3"},"vol3:fig-vol3-utility-vs-attack-success":{"key":"vol3:fig-vol3-utility-vs-attack-success","figure_id":"fig-vol3-utility-vs-attack-success","source":"books/vol3/09_security/09_security.qmd","title":"Utility Does Not Buy Resistance","status":"ready","treatment":"annotated","question":"Can benign task utility stand in for resistance to an injection attack?","scope":"Dots and defense arrows are recorded evaluations, not an interpolated response surface. Only one model was evaluated under every shown defense; these measurements do not rank defenses for all models.","regions":{"baseline":{"x":0.63,"y":0.17,"w":0.04,"h":0.06,"label":"Undefended GPT-4o anchor"},"sameutility":{"x":0.74,"y":0.36,"w":0.24,"h":0.53,"label":"Similar-utility model revisions"},"delimit":{"x":0.64,"y":0.2,"w":0.15,"h":0.1,"label":"Delimiting endpoint"},"detector":{"x":0.18,"y":0.71,"w":0.18,"h":0.09,"label":"Injection-detector endpoint"},"filter":{"x":0.65,"y":0.74,"w":0.11,"h":0.08,"label":"Tool-filter endpoint"},"repeat":{"x":0.74,"y":0.45,"w":0.17,"h":0.09,"label":"Repeat-user-prompt endpoint"},"axes":{"x":0.01,"y":0.03,"w":0.08,"h":0.84,"label":"Targeted attack-success axis"}},"steps":[{"title":"Compare resistance at similar utility","description":"The two labeled Claude 3.5 Sonnet revisions have similar benign utility but very different targeted attack success. Benign capability does not determine resistance to this attack.","focus":["sameutility"]},{"title":"Keep the defense comparison matched","description":"All colored arrows start at the same undefended GPT-4o point. Delimiting and repeating the user prompt lead to different measured endpoints, not a general formula for resistance.","focus":["baseline","delimit","repeat"]},{"title":"Count the cost in useful work","description":"The injection detector lowers attack success while moving left to lower benign utility. Security evaluation must retain this useful-work loss rather than reward blocking alone.","focus":["detector","axes"]},{"title":"Inspect the constrained-tool result","description":"The tool filter endpoint moves down and slightly right from the anchor in this evaluation. The result supports checking both metrics together, without assuming the same effect for untested models.","focus":["baseline","filter"]}],"artwork_reviewed":true,"art_sha1":"9805a7c7a0fdf9877053bf998dd232ecca376b85","art_kind":"png","art_width":4402,"art_height":2637},"vol3:fig-vol3-verifier-cascade":{"key":"vol3:fig-vol3-verifier-cascade","figure_id":"fig-vol3-verifier-cascade","source":"books/vol3/15_trajectory_curation/15_trajectory_curation.qmd","title":"One Admission Route","status":"ready","treatment":"annotated","question":"How do pass, fail, and pending results change admission to one training route?","scope":"Admission is route-specific. A rejected record stays available for diagnosis or other routes, and pending or unknown results never count as passes.","regions":{"predicates":{"x":0.19,"y":0.02,"w":0.57,"h":0.17,"label":"R, U, P, O, T predicates"},"admitted":{"x":0.02,"y":0.24,"w":0.96,"h":0.16,"label":"Record A passes all predicates"},"rejected":{"x":0.02,"y":0.48,"w":0.96,"h":0.18,"label":"Record B fails outcome"},"hold":{"x":0.02,"y":0.73,"w":0.96,"h":0.23,"label":"Record C remains pending"}},"steps":[{"title":"Follow the declared predicate order","description":"The route checks record adequacy, permitted use, process, outcome, and target suitability. A record needs a pass at every predicate before this route can admit it.","focus":["predicates","admitted"]},{"title":"Stop on the first failure","description":"Record B passes the first three checks and fails outcome. Target suitability is not run; the record is rejected for this route and retained rather than deleted.","focus":["rejected"]},{"title":"Keep missing evidence unresolved","description":"Record C reaches a pending permitted-use check. Later checks are not run, and the route holds the record without treating missing evidence as acceptance or rejection.","focus":["hold"]}],"artwork_reviewed":true,"art_sha1":"46a74d0fb70fb47d93875eafb6b6ef53c5a11c0c","art_kind":"svg","art_width":1200,"art_height":558,"art_structural_sha1":"a61b76f14e4310a3a189f785dd4ba470fa506fbf"},"vol3:fig-vol3-working-set-selection":{"key":"vol3:fig-vol3-working-set-selection","figure_id":"fig-vol3-working-set-selection","source":"books/vol3/04_context_engineering/04_context_engineering.qmd","title":"Selection Protects the State Budget","status":"ready","treatment":"annotated","question":"How can a long trajectory retain useful state without filling every prompt?","scope":"The bars are a context-budget schematic, not measured byte occupancy or an exact additive tokenizer identity.","regions":{"append":{"x":0.04,"y":0.05,"w":0.43,"h":0.84,"label":"Append-every-result columns"},"squeeze":{"x":0.27,"y":0.23,"w":0.19,"h":0.5,"label":"State displaced by observations"},"selected":{"x":0.53,"y":0.05,"w":0.32,"h":0.84,"label":"Selected working sets"},"records":{"x":0.87,"y":0.18,"w":0.12,"h":0.51,"label":"Retained records and handles"},"reserve":{"x":0.15,"y":0.16,"w":0.69,"h":0.13,"label":"Output headroom boundary"}},"steps":[{"title":"Reserve room for an answer","description":"The hatched region remains reserved for output. Incoming context must fit below the Smax minus Kmax boundary.","focus":["reserve"]},{"title":"Watch observations crowd out state","description":"Appending every result grows the orange observation portion. By turn t+2 the green task state is squeezed.","focus":["append","squeeze"]},{"title":"Select for the next decision","description":"The selected-working-set columns keep the state share while limiting observations staged into the next call. Selection changes the prompt, not what happened historically.","focus":["selected"]},{"title":"Retain evidence outside the prompt","description":"Records can remain available behind handles and be retrieved when needed. Omitting them from the active prompt need not delete them.","focus":["records"]}],"artwork_reviewed":true,"art_sha1":"03ba82538b69f6d72e9e8f7cd5bdaf9074f43f32","art_kind":"svg","art_width":1200,"art_height":653,"art_structural_sha1":"9e3d48f8b28c123d1d5d15bd74ca14abe9320901"}});
